(window.__BOOKS=window.__BOOKS||{})["e_iphaul"]={"b":[["sd","(«<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>-жертва»)"],["h2","Действующие лица"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span></span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Старик-раб</span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Хор женщин из Авлиды</span>"],["person","<span class=\"pn\">Корифей, пожилая женщина</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"menelay\">Менелай</span></span> <span class=\"act-no\">(I)</span>"],["person","<span class=\"pn\">Первый вестник</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span></span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span></span> <span class=\"act-no\">(I)</span>"],["person","<span class=\"pn\">При них Орест (без речей)</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"ahill\">Ахилл</span></span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Второй вестник</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Стража <span class=\"ch\" data-ch=\"agamemnon\">Агамемнона</span> и отряд <span class=\"ch\" data-ch=\"ahill\">Ахилла</span>. Свита <span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестры</span>.</span>"],["place","Действие происходит в Авлиде перед царским шатром Агамемнона, в ожидании троянского похода."],["act","Пролог","a1",""],["sd","Ночь. Ни ветерка. Ярко горят звезды. Шатер <span class=\"ch\" data-ch=\"agamemnon\">Агамемнона</span>. Вдали заснувшее морское побережье с отсвечивающею полосою воды. Суда с повисшими парусами; иные вырисовываются черными контурами на белой отмели. Лагерь спит."],["scene","Явление первое","s1",1,1],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["dir","выходит из шатра и несколько времени в волнении ходит по сцене, по временам останавливаясь около шатра; он без оружия; в руке у него запечатанная табличка с письмом; остановившись у входа в палатку и по направлению к ней"],["v","Гей!..",0,1,0,0],["sd","Пауза."],["v","Отзовись из шатра, старик,",0,1,0,0],["v","Спишь ли? Выйди на царский зов.",0,1,0,0],["sp","Старик"],["dir","еще из шатра"],["v","Здесь я, здесь я, владыка-царь.",0,1,0,0],["v","Что придумать изволил,",0,1,0,0],["v","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>?",0,1,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Все узнаешь сейчас…",0,1,0,0],["sp","Старик"],["dir","выходит из шатра и кланяется царю"],["v","Приказаний жду…",1,1,0,0],["v","Моя старость, владыка, бессонная,",0,2,0,0],["v","А глаза у нее — что два сторожа.",0,3,0,0],["sd","Пауза."],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["dir","молча блуждает взором по небу, потом к старику, указывая ему на небо"],["v","Скажи, старик, какая там звезда",0,4,0,0],["v","По небу катится?",0,5,0,0],["sp","Старик"],["dir","тоже смотря в небо"],["v","То Сириус, владыка,",1,5,0,0],["v","Семи Плеяд созвездия настигла",0,6,0,0],["v","И возле них небесный держит путь,",0,7,0,0],["v","А что прошла, ей столько ж остается…<a class=\"nr\" href=\"#n-k2\" data-n=\"k2\" aria-label=\"Примечание 2\">2</a>",0,8,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Какая тишь… Ни звука… Хоть бы птица,",0,9,0,0],["v","Иль моря всплеск… Молчанием Еврип<a class=\"nr\" href=\"#n-k3\" data-n=\"k3\" aria-label=\"Примечание 3\">3</a>",0,10,0,1],["v","Воздушным будто скован…",0,11,0,0],["sp","Старик"],["v","Но сдается…",1,11,0,0],["v","Встревожен ты, мой добрый господин?",0,12,2,0],["v","Шатер забыт! А между тем в Авлиде",0,13,2,0],["v","Так мирно все. И даже на стенах",0,14,2,0],["v","Смениться не успели караулы.",0,15,2,0],["sd","(Жестом приглашает его в шатер и почтительно:)"],["v","Вернемся, царь…",0,16,2,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["dir","со вздохом и смотря на старика"],["v","Как счастлив ты, старик!",1,16,0,0],["v","Как я тебе завидую, что можешь",0,17,0,0],["v","Ты век прожить в безвестности… Мне тот,",0,18,0,0],["v","Кто вознесен судьбою, только жалок…",0,19,0,0],["sp","Старик"],["v","Но где же счастье, царь, как не у вас.",0,20,0,1],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","А долго ли оно нас тешит, старец?",0,21,0,0],["v","Приманка сладкая, а откусить — претит…",0,22,0,0],["v","То бог казнит обиженный и счастье",0,23,0,0],["v","Нам рушит в прах, а завтра, смотришь, люди,",0,24,0,0],["v","Толпа капризная его на клочья рвут…",0,25,0,0],["sp","Старик"],["dir","строго"],["v","Что говоришь ты, царь,",0,26,2,0],["v","Что говоришь?",0,27,2,0],["v","Или ты мнить дерзал,",0,28,2,0],["v","Что на бессменное",0,29,2,0],["v","Счастье родил Атрей",0,30,2,1],["v","Сына вельможного?",0,30,2,0],["v","Смертнорожденному",0,31,2,0],["v","Боги в удел дают",0,32,2,0],["v","Счастье с печалями.",0,33,2,0],["v","Божье веление,",0,33,2,0],["v","Рад ли, не рад, терпи…",0,34,2,0],["v","Но ты всю ночь светильник жег и доску",0,35,0,0],["v","Писаньем покрывал. Вон у тебя",0,36,0,0],["v","Она в руках и до сих пор — я видел,",0,36,0,0],["v","Как ты стирал письмо, потом печатью",0,37,0,0],["v","Его крепил, потом, печать сорвав,",0,38,0,0],["v","О землю ударял доской, и слезы, слезы",0,39,0,0],["v","Обильные вдоль щек твоих текли.",0,40,0,1],["v","И мне порой казалось, что безумец",0,41,0,0],["v","Передо мной… Ты болен, государь?",0,42,0,0],["v","Тебя терзает что-нибудь? Поведай",0,43,0,0],["v","Мне слово тайное. Перед тобою раб,",0,44,0,0],["v","Доверия достойный, и недаром",0,45,0,0],["v","Еще Тиндар в приданое невесте",0,46,0,0],["v","В твой царский дом меня определил.",0,47,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Трех дочерей на свет явила Леда:<a class=\"nr\" href=\"#n-k4\" data-n=\"k4\" aria-label=\"Примечание 4\">4</a>",0,48,2,0],["v","Звалася Фебой первая из них,",0,49,2,0],["v","Жена моя, вторая, Клитемнестрой,<a class=\"nr\" href=\"#n-k5\" data-n=\"k5\" aria-label=\"Примечание 5\">5</a>",0,50,2,1],["v","И младшая Еленой.",0,50,2,0],["v","Женихов",1,50,0,0],["v","Прославленных в Элладе и могучих",0,51,2,0],["v","Ее краса манила, и вражды",0,52,2,0],["v","Зажглось меж ними пламя: уж носились",0,53,2,0],["v","Кровавые угрозы по устам,",0,53,2,0],["v","Суля ее избраннику расправу…",0,54,2,0],["v","Уж голову старик Тиндар терял,",0,55,2,0],["v","Ее отец, колеблясь, выдавать ли",0,56,2,0],["v","Иль лучше дочь совсем не выдавать, —",0,56,2,0],["v","И вдруг его решенье осеняет —",0,57,2,0],["v","И юношам он молвит: \"Женихи,",0,58,2,0],["v","Клянитесь мне, соединив десницы",0,59,2,0],["v","И пепел жертв обильно оросив,",0,60,2,1],["v","Спасать от бед избранника невесты,",0,61,2,0],["v","И если кто, будь варвар то иль грек,",0,62,2,0],["v","Столкнув его с Елениного ложа,",0,63,2,0],["v","Тиндара дочь в свой город увезет, —",0,64,2,0],["v","Клянитесь мне разрушить стены вражьи\".",0,65,2,0],["v","Так царь Тиндар, опутав женихов",0,66,2,0],["v","И клятвою связав их, дочке отдал:",0,67,2,0],["v","\"Любого, дочь, ты выберешь — плыви,",0,68,2,0],["v","Куда влечет Киприды дуновенье\".",0,69,2,0],["v","Был выбором отмечен <span class=\"ch\" data-ch=\"menelay\">Менелай</span>.",0,70,2,1],["v","О, горе нам!.. Но годы шли… Фригиец,",0,70,2,0],["v","Решивший спор богинь — так говорит<a class=\"nr\" href=\"#n-k6\" data-n=\"k6\" aria-label=\"Примечание 6\">6</a>",0,71,2,0],["v","Предание, в Лакедемон приехал:",0,72,2,0],["v","Цветами на одеждах ослепив,",0,73,2,0],["v","Весь золотом увешанный, как варвар,",0,73,2,0],["v","С царицею влюбленный Приамид",0,74,2,0],["v","Влюбленною уплыл к родимой Иде,",0,75,2,0],["v","Пока по свету ездил <span class=\"ch\" data-ch=\"menelay\">Менелай</span>…",0,76,2,0],["v","Но вот домой вернулся царь: язвимый",0,76,2,0],["v","Любовью и обидою, он шлет",0,77,2,0],["v","Во все края Эллады, чтоб о клятве",0,78,2,0],["v","Припомнили ахейцы… На призыв",0,79,2,0],["v","Воздвиглись копья мигом и немедля",0,80,2,1],["v","Среди щитов блестящих женихи",0,80,2,0],["v","Под парусом, на бранных колесницах,",0,81,2,0],["v","Близ тесных вод авлидских собрались",0,82,2,0],["v","И стали лагерем.",0,83,2,0],["v","А мне команда",1,83,0,0],["v","Поручена по выбору… Еще бы…",0,83,2,0],["v","Ведь <span class=\"ch\" data-ch=\"menelay\">Менелай</span> мне брат… О, эту честь,",0,84,2,0],["v","А с ней и жезл охотно бы я отдал…",0,85,2,0],["v","Окончены все сборы, и давно",0,86,2,0],["v","К отплытию готов наш флот, да ветра",0,86,2,0],["v","Бог не дает… И вот Калхант-вещун",0,87,2,0],["v","Средь воинов, безвременьем томимых,",0,88,2,0],["v","Изрек, что царь и вождь <span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>",0,89,2,0],["v","Дочь <span class=\"ch\" data-ch=\"ifigeniya\">Ифигению</span>, свое рожденье, должен",0,90,2,1],["v","На алтаре богини заколоть,<a class=\"nr\" href=\"#n-k7\" data-n=\"k7\" aria-label=\"Примечание 7\">7</a>",0,90,2,0],["v","Царицы гладей этих. \"Если, молвил,",0,91,2,0],["v","Заколете девицу, будет вам",0,91,2,0],["v","И плаванье счастливое, и город",0,92,2,0],["v","Вы вражеский разрушите, а нет —",0,93,2,0],["v","Так ничего не сбудется\". Об этом",0,93,2,0],["v","Пророчестве узнав, оповестить",0,94,2,0],["v","Через Талфибия-герольда приказал я",0,95,2,0],["v","Дружины наши, что родную дочь",0,95,2,0],["v","Я никогда зарезать не отважусь.",0,96,2,0],["sd","(Приостанавливается, потом изменившимся голосом.)"],["v","Увы! Зачем меня речами брат",0,96,2,0],["v","Сумел склонить на злое дерзновенье?",0,97,2,0],["sd","(Показывает старику на письмо.)"],["v","Вот на таком же складне написав,",0,98,2,0],["v","Безумное я отдал приказанье",0,98,2,0],["v","Жене, чтобы сюда прислала дочь: (с горькой усмешкой)",0,99,2,0],["v","Мол, Ахиллес ей руку предлагает…",0,100,2,1],["v","А к тем словам добавил, что герой",0,100,2,0],["v","Не хочет с нами разделить похода,",0,101,2,0],["v","Коль в жены <span class=\"ch\" data-ch=\"ifigeniya\">Ифигению</span> ему",0,102,2,0],["v","Я не отдам и ложа не разделит",0,103,2,0],["v","Во Фтии с ним царевна… Я в письме (совсем тихо)",0,103,2,0],["v","Перед женою лгал, блестящим браком",0,104,2,0],["v","Ее прельстить желая… И об этом",0,105,2,0],["v","Здесь знают только трое… <span class=\"ch\" data-ch=\"menelay\">Менелай</span>",0,106,2,0],["v","Да Одиссей с Калхантом.",0,106,2,0],["sd","Пауза."],["v","О, решенье",1,106,0,0],["v","Позорное отброшено, — теперь",0,107,0,0],["v","Как следует я все списал на эту",0,108,0,0],["v","Дощечку, и сегодня ты, старик,",0,109,0,0],["v","Меня как раз за этим ночью видел,",0,110,0,1],["v","Когда печать срывал я и лепил.",0,110,0,0],["sd","(Показывает ему письмо.)"],["v","Иди, старик, с моим посланьем в Аргос;",0,111,0,0],["v","А чтоб ты знал, какую весть несешь,",0,112,0,0],["v","Я верному слуге жены и дома",0,113,0,0],["v","Ее сейчас словами передам…",0,114,0,0],["sp","Старик"],["v","Да, царь, письмо ты объясни мне речью,",0,115,0,0],["v","Чтоб мой язык согласно с ним вещал…",0,116,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","\"Чадо Леды, тебе мой приказ,",0,117,0,0],["v","А что раньше прочла — позабудь!..",0,118,0,0],["v","На глубокую заводь Евбеи",0,119,0,0],["v","Деву-дочь, царица, не шли",0,120,0,1],["v","К бесприбойным авлидским брегам…",0,120,0,0],["v","Брачный факел ее сбережем",0,121,0,0],["v","Мы до лучших дней, Тиндарида…\"",0,122,0,0],["sp","Старик"],["v","Царь, а как же <span class=\"ch\" data-ch=\"ahill\">Ахилл</span>?<a class=\"nr\" href=\"#n-k8\" data-n=\"k8\" aria-label=\"Примечание 8\">8</a>",0,123,0,0],["v","Иль, ты думаешь, стерпит надменный,",0,124,0,0],["v","Или гневом тяжким не вспыхнет",0,125,0,0],["v","На тебя и на мать невесты,",0,125,0,0],["v","Коль обман Атридов откроет?",0,126,0,0],["v","Царь, подумал ли ты об <span class=\"ch\" data-ch=\"ahill\">Ахилле</span>?",0,127,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","О, Пелид — это только предлог,",0,128,0,0],["v","Это имя… он даже не знает,",0,129,0,0],["v","Что невесту ему сулил я,",0,130,0,1],["v","Что ему для брачных объятий",0,131,0,0],["v","Обрекали на ложе деву.",0,132,0,0],["sp","Старик"],["dir","покачав головой"],["v","Дерзновенен ты, о Микенский царь,",0,133,0,0],["v","Коли сыну бессмертной",0,134,0,0],["v","Обрученную в мыслях смел",0,135,0,0],["v","Под нож осуждать данайский.",0,136,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["dir","проникаясь его тоном"],["v","Да, старик, я безумием был",0,137,0,0],["v","Охвачен, я гибну, старец!",0,138,0,0],["v","О, спеши и годы забудь",0,139,0,0],["v","На стопах окрыленных…",0,140,0,1],["sp","Старик"],["v","Я готов, <span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>-царь.",0,141,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","У ручья и в роще, старик,",0,142,0,0],["v","Ты не нежь там старые кости.",0,143,0,0],["v","Пусть тебя и сон не чарует…",0,144,0,0],["sp","Старик"],["v","Сохрани меня бог.",0,145,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","На распутьях ты",1,145,0,0],["v","Проглядеть колесницу можешь…",0,146,0,0],["v","Зорко, в оба ты, старец, гляди.",0,147,0,0],["sd","(Касаясь его руки, живо.)"],["v","А увидишь, что мимо тебя",0,148,0,0],["v","Царевну везут по стану,",0,149,0,0],["v","Прицепись к колеснице, старик,",0,150,0,1],["v","У возницы ты вожжи возьми",0,150,0,0],["v","И ворочай на белые стены…",0,151,0,0],["sp","Старик"],["v","Хорошо.",0,152,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Поскорей, поскорей!",1,152,0,0],["sp","Старик"],["v","Да поверят ли мне, господин,",0,153,0,0],["v","Царица твоя и царевна?",0,154,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Ты об этом не думай, старик!",0,155,0,0],["v","Только целой печать сохрани…",0,156,0,0],["v","…Но не медли, не медли, — мерцая,",0,157,0,0],["v","Уж заря загорелась, и скоро",0,158,0,0],["v","Колесница Гелия бога",0,159,0,0],["v","Тень и ночь в небесах рассеет.",0,160,0,1],["v","Старик уходит. <span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span> вслед ему.",0,160,0,0],["v","О, сними тяготу мне с сердца.",0,161,0,0],["sd","Пауза."],["v","В этой жизни из смертных никто",0,162,0,0],["v","Не изведал присноблаженства,",0,163,0,0],["v","Чаши мук не ушел ни единый.",0,163,0,0],["sd","(Уходит в шатер.)"],["sd","Чуть брезжит рассвет. На сцену поднимается хор. В лагере начинается движение."],["scene","Вступительная песнь хора","s2",1,2],["sp","Хор"],["str","Строфа I"],["v","К вам я, волны авлидские,<a class=\"nr\" href=\"#n-k1\" data-n=\"k1\" aria-label=\"Примечание 1\">1</a>",0,164,0,0],["v","Волны пенно-соленые,",0,165,0,0],["v","Шла берегами песчаными.",0,166,0,0],["v","И воды Еврипа тесного",0,166,0,0],["v","Мой, рассекая, спешил челнок.",0,167,0,0],["v","Я Халкиды возлюбленной<a class=\"nr\" href=\"#n-k9\" data-n=\"k9\" aria-label=\"Примечание 9\">9</a>",0,168,1,0],["v","Стены родные покинула,",0,169,1,0],["v","И Аретусы славной,<a class=\"nr\" href=\"#n-k10\" data-n=\"k10\" aria-label=\"Примечание 10\">10</a>",0,170,1,1],["v","С гулом морским слитый,",0,171,1,0],["v","Милый шум позабыла.",0,172,1,0],["v","Видеть ахейцев душа горит",0,173,0,0],["v","Рати суровые,",0,174,0,0],["v","Что с <span class=\"ch\" data-ch=\"agamemnon\">Агамемноном</span>",0,175,0,0],["v","За Тиндаридою",0,176,0,0],["v","Царь ведет златокудрый.",0,177,0,0],["v","Так говорили мне:",0,178,0,0],["v","Дивную с брега Еврота зеленого",0,179,0,0],["v","Пастырь Парис увлек,",0,180,0,1],["v","В дар от Киприды прияв ее.",0,180,0,0],["v","Возле потока недаром он,",0,181,1,0],["v","Возле жемчужно-росистого,",0,182,1,0],["v","Ей присудил красоты венец",0,183,1,0],["v","В споре с Палладой и Герою.",0,184,1,0],["str","Антистрофа I"],["v","Рощей девы Латонии,",0,185,0,0],["v","Полной жертвокурения,",0,186,0,0],["v","Ноги несли меня быстрые…",0,187,0,0],["v","Но только лагеря пестрого",0,188,0,0],["v","Пламя щитов увидала я,",0,189,0,0],["v","Сбруи медной сверкание, —",0,190,1,1],["v","Краской стыдливости розовой",0,191,1,0],["v","Вспыхнули вмиг ланиты.",0,192,1,0],["v","Там двух Аяксов славных,",0,193,1,0],["v","Над доскою склоненных,",0,194,1,0],["v","Видела жадно следивших я",0,195,0,0],["v","Ходы мудреные…",0,196,0,0],["v","Был Паламед при них —",0,197,0,0],["v","Навплия мудрый сын.",0,198,0,0],["v","Мышцы рук напрягая,",0,199,0,0],["v","Диск там Тидид метал.",0,200,0,1],["v","Им Мерион любовался, Аресов сын,",0,200,0,0],["v","Чудо меж смертными.",0,201,0,0],["v","Там и Лаэртом рожденного",0,202,0,0],["v","Зрела я скал повелителя;",0,203,1,0],["v","Там и Нирей мне герой предстал,",0,204,1,0],["v","Муж, что красою сияющей",0,205,1,0],["v","Равных не знает меж эллинов.",0,205,1,0],["str","Эпод"],["v","Там и повитый Фетидою,",0,206,0,0],["v","Мудрым Кентавром взлелеянный,",0,207,0,0],["v","Взоры <span class=\"ch\" data-ch=\"ahill\">Ахилл</span> пленял,",0,208,0,0],["v","Ветра соперник…",0,209,0,0],["v","Он по каменьям острым,",0,210,1,1],["v","Берегом близ колесницы,",0,211,1,0],["v","В панцире, в тяжких латах",0,212,1,0],["v","Мчался, с четверкой споря…",0,213,1,0],["v","Ферета даром внук,",0,214,0,0],["v","Славный Евмел-герой",0,215,0,0],["v","Криком коней бодрил;",0,216,1,0],["v","Тщетно стрекалом он",0,217,1,0],["v","Жег златоуздых пыл.",0,220,1,1],["v","В очи мелькнули мне",0,220,1,0],["v","Два дышловых коня:",0,221,1,0],["v","Буро-сребристые,",0,222,0,0],["v","Ноги с подпалиной;",0,222,0,0],["v","Но пристяжные два,",0,223,1,0],["v","На поворотах лишь",0,224,1,0],["v","Силой им равные,",0,225,1,0],["v","Даром взметали прах…",0,225,1,0],["v","Вот уж в виду мета, —",0,226,1,0],["v","И окольчуженный",0,227,1,0],["v","Уж обогнал Пелид",0,227,1,0],["v","Руки Евмеловы…",0,228,1,0],["v","Вот он ярмо настиг:",0,229,0,0],["v","Будет с победою…",0,230,0,1],["str","Строфа II"],["v","Полюбилось сосчитать",0,230,1,0],["v","Тьмы ахейских кораблей,",0,231,1,0],["v","Чтоб и восторга и жалости блеском",0,232,0,0],["v","Загорелся женский взор.",0,233,1,0],["v","Там, где брызжет вал",0,234,3,0],["v","В правое крыло,",0,235,3,0],["v","Там фтиотские ладьи",0,235,1,0],["v","Мирмидонский держит вождь.",0,236,1,0],["v","Пятьдесят судов —",0,237,3,0],["v","Пятьдесят богинь",0,238,3,0],["v","Их в изваяньях златых охраняют:",0,239,0,0],["v","То Нереиды, кормы украшенье;",0,240,0,1],["v","Их <span class=\"ch\" data-ch=\"ahill\">Ахилла</span> войско чтит.",0,240,1,0],["str","Антистрофа II"],["v","Равные числом стоят",0,241,1,0],["v","Рядом Аргоса ладьи,",0,242,1,0],["v","Правят прекрасными сын Мекистея",0,243,0,0],["v","И Сфенел, ретивый вождь.",0,243,1,0],["v","Шестьдесят затем",0,244,3,0],["v","Из Афин привел",0,245,3,0],["v","Сильного Тесея сын.",0,246,1,0],["v","Их не трудно распознать:",0,246,1,0],["v","Ведь на всех зарей",0,247,3,0],["v","Золотой горит",0,248,3,0],["v","Лик вдохновенный Паллады могучей;",0,249,0,0],["v","Грозно она колесницей крылатой",0,250,0,1],["v","Правит, ясный знак пловцам.",0,251,1,0],["str","Строфа III"],["v","Беотян затем снаряженье морское",0,252,0,0],["v","Увидели мы: пятьдесят легкокрылых",0,253,0,0],["v","Судов колышет волн прибой.",0,254,1,0],["v","На них сверкает Кадм;",0,255,3,0],["v","Поверженного змея",0,256,3,0],["v","Пятой смиряет он.",0,257,3,0],["v","А правит бесстрашною ратью плавучей",0,258,0,0],["v","Землей рожденный царь Леит.",0,260,1,1],["v","Такой же силы вождь",0,261,3,0],["v","За ними держит след —",0,262,3,0],["v","Аякс, повелитель фокейцев и локров,",0,263,0,0],["v","Покинув Фроний, стольный град.",0,264,1,0],["str","Антистрофа III"],["v","А далее златом обильных Микен",0,265,0,0],["v","Красуются струги; их сто собралося,",0,266,0,0],["v","И вождь им всем — Атрея сын.",0,267,1,0],["v","Но там же и Адраст —",0,268,3,0],["v","А друг он верный другу;",0,269,3,0],["v","Грозит беглянке он,",0,270,3,1],["v","Что бросила дом ради варварской свадьбы,",0,271,0,0],["v","Напомнить эллинский закон.",0,272,1,0],["v","Вблизи пилосский царь",0,273,3,0],["v","Взор, Нестор, наш пленил;",0,274,3,0],["v","Знак турокопытный ладьи его красит —",0,275,0,0],["v","Алфей, реки родимой бог.",0,276,1,0],["str","Эпод"],["v","Рядом стоят — дюжина всех —",0,277,0,0],["v","Смелых суда энианов;",0,278,1,0],["v","В бой их ведет витязь Гуней.",0,279,0,0],["v","Далее — дети Элиды,",0,280,1,1],["v","Их же эпейцами кличет народ,",0,281,0,0],["v","Бранная сила Еврита.",0,282,1,0],["v","Далее беловесельных мужей",0,283,0,0],["v","С Тафа Мегет направляет,",0,284,1,0],["v","Имя отца хочет герой,",0,285,0,0],["v","Старца Филея, прославить:",0,286,1,0],["v","Ради него цепь Эхинад",0,287,0,0],["v","Бросил, пловцам недоступных.",0,288,1,0],["v","В левом крыле гордый Аякс,",0,289,0,0],["v","Витязь стоит саламинский;<a class=\"nr\" href=\"#n-k11\" data-n=\"k11\" aria-label=\"Примечание 11\">11</a>",0,290,1,1],["v","Правому он близкий сосед,",0,291,0,0],["v","Чуть не сплелись кораблями.",0,292,1,0],["v","Только двенадцать ведет он судов —",0,293,0,0],["v","Да, но ловчее не встретишь.",0,294,1,0],["v","Вот наша сила. Пусть сцепится враг,",0,295,0,0],["v","Вмиг о возврате забудет.",0,296,1,0],["v","Сами суда видели мы;",0,297,0,0],["v","Про остальное поведал",0,300,1,1],["v","Дома народ; память храним",0,301,0,0],["v","Вести и зрелища свято.",0,302,1,0],["sd","Раннее утро."],["act","Действие первое","a2","I"],["scene","Явление второе","s3",2,3],["sd","Старик и <span class=\"ch\" data-ch=\"menelay\">Менелай</span>."],["sd","На сцену поспешно выбегает старик; он силится отнять письмо у <span class=\"ch\" data-ch=\"menelay\">Менелая</span>, который идет перед ним большими шагами, тоже несколько взволнованный."],["sp","Старик"],["v","Стыдись, Атрид… Ведь это ж преступленье!",0,303,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Прочь, говорят, не в меру верный раб!",0,304,0,0],["sp","Старик"],["v","Такою бранью я готов гордиться…",0,305,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Смотри, побью — заплачешь вдругорядь.",0,306,0,0],["sp","Старик"],["v","Прочесть письмо чужое… и не стыдно?",0,307,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Стыдился б сам ахейцам яму рыть…",0,308,0,0],["sp","Старик"],["v","С царями спорь, а мне — письмо, ты слышишь?",0,309,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Нет, подождешь…",0,310,0,1],["sp","Старик"],["v","Письмо отдай, письмо…",1,310,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Оставь, старик: жезлом тяжелым царским",0,310,0,0],["v","Я голову тебе раскровеню.",0,311,0,0],["sp","Старик"],["v","Ну что ж? Рабу бесчестия не будет,",0,312,0,0],["v","Коль примет смерть он за своих господ.",0,312,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Эй, замолчи, слуга многоречивый!",0,313,0,0],["sp","Старик"],["v","Не замолчу…",0,314,0,0],["sd","(Кричит, обращаясь к шатру.)"],["v","О царь <span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>!",0,314,4,0],["v","Твое письмо в чужих руках, и силой",0,315,0,0],["v","Им завладел обидчик… Выручай!",0,316,0,0],["scene","Явление третье","s4",2,4],["sd","Те же и <span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span> (в шлеме, но без оружия выходит из шатра недовольный. Сначала он еще не видит <span class=\"ch\" data-ch=\"menelay\">Менелая</span>. Первый стих — за сценой)."],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Гей!",0,316,0,0],["v","Что за шум под царской дверью: брань, смятение и крик?",0,317,0,0],["sd","(Видит раба.)"],["v","Что случилось и зачем ты вызывал меня, старик?",0,318,0,0],["sd","(Замечает <span class=\"ch\" data-ch=\"menelay\">Менелая</span>, но не оборачивается к нему.)"],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","обиженно"],["v","Мне держать ответ приличней, чем холопу твоему.",0,318,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","оборачиваясь к нему"],["v","Ты чего же тут воюешь и зачем грозишь ему?",0,319,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","в его тоне"],["v","Посмотри в глаза мне прямо — после будет разговор.",0,320,0,1],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["dir","несколько смущенный, потому что увидел письмо в руках брата, но поднимает на него глаза"],["v","Сын Атрея не умеет опускать в смущенье взор…",0,321,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","показывает письмо"],["v","Узнаешь ты этот складень, эти злые начертанья?",0,322,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Я не слеп. Изволь немедля возвратить гонцу посланье!",0,323,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Нет, его узнают прежде все данайцы, понимаешь?",0,324,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","А с каких же пор ты письма посторонние вскрываешь?",0,325,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","иронически"],["v","Да, к несчастью, Агамемнон, нам известен твой секрет.",0,326,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Что тебе известно? Совесть потерял ты вовсе, что ли?",0,327,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Мне давно узнать хотелось, ждать царевны или нет?",0,328,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Да стеречь мою семью-то чьей же ты поставлен волей?",0,329,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Успокойся, не твоею, не бывал твоим рабом.",0,330,0,1],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["dir","в прежнем тоне"],["v","О, неслыханная дерзость! Твой он, что ль, микенский дом?",0,330,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","сдержанно"],["v","Ты обижен — что же делать? Веры в нас к тебе не стало.",0,331,0,0],["v","«Да» — вчера, и «нет» — сегодня, а назавтра — все сначала.",0,332,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["dir","в его тоне, иронически"],["v","Гладкослов, язык твой ловкий, право, стоит очень мало.",0,333,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Шаткий ум твой не дороже. Что он даст друзьям, скажи?",0,334,0,0],["sd","(Выждав.)"],["v","Право, лучше, Агамемнон, гнев свой жаркий отложи.",0,335,0,0],["v","Я не буду горячиться, — ты же, истину любя,",0,335,0,0],["v","Не посетуй, коль увидишь, точно в зеркале, себя.",0,336,0,0],["v","Вспомни, как душой горел ты стать вождем союзных ратей,",0,337,0,0],["v","Сколько ран душевных прятал под расшитый свой гиматий!",0,338,0,0],["v","Вспомни, как ты унижался, черни руки пожимая,<a class=\"nr\" href=\"#n-k12\" data-n=\"k12\" aria-label=\"Примечание 12\">12</a>",0,339,0,0],["v","Как дверей не запирал ты, без разбору принимая,",0,340,0,1],["v","Как со всеми по порядку ты беседовал учтиво,",0,340,0,0],["v","И врагов и равнодушных уловляя фразой льстивой…",0,341,0,0],["v","И с ахейцами торгуясь за надменную утеху,",0,342,0,0],["v","Чем тогда ты, Агамемнон, не пожертвовал успеху?",0,343,0,0],["v","А потом, добившись власти, вспомни, как ты изменился,",0,343,0,0],["v","От друзей своих недавних как умело отстранился!",0,344,0,0],["v","Неприступен и невидим стал наш вождь. Не так бывает",0,345,0,0],["v","С мужем чести, если жребий путь широкий открывает",0,346,0,0],["v","Перед ним: сильней он любит друга, в горе нажитого,",0,346,0,0],["v","Рад он лить ему усладу из бокала золотого;",0,347,0,0],["v","Он доступней, потому что стал сильнее и богаче…",0,348,0,0],["v","Ты же, царь, ребячью душу обнаружил средь удачи…",0,349,0,0],["v","Помнишь: мы пришли в Авлиду, но попутчика не слали",0,350,0,1],["v","Боги нам из стаи ветров; и ахейцы возроптали.",0,350,0,0],["v","«Распусти нас, говорили, жить в Авлиде нам постыло».",0,351,0,0],["v","Ты как тень бродил печально: жалоб, жалоб что тут было!",0,352,0,0],["v","Царь в мечтах уж видел тучи парусов под Илионом,",0,353,0,0],["v","Он копьем делил нам нивы… А меж тем с бессильным стоном",0,354,0,0],["v","Приставал ко мне: «Что делать? Чем поможем мы несчастью?»",0,355,0,0],["v","О Атрид, ты видел выход, да жалел проститься с властью!",0,356,0,0],["v","Помнишь, как ты был ничтожен, за борт выброшен судьбою?",0,357,0,0],["v","А когда Калхант-гадатель Артемиде для убоя",0,358,0,0],["v","Дочь твою обрек на жертву, путь взамен суля счастливый,",0,359,0,0],["v","Помнишь, как ты духом ожил, как в надежде торопливой",0,360,0,1],["v","Сам, никем не принуждаем, написал, чтоб Тиндарида",0,361,0,0],["v","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигению</span> прислала, — мол, невесту для Пелида?",0,362,0,0],["v","Ну, уладил дело… Как же! Снова шлются уверенья…",0,363,0,0],["v","Царь раскаяться изволил в самой мысли преступленья…",0,364,0,0],["v","Но ведь солнце не погасло, что и те слова слыхало?",0,365,0,0],["v","О, вас тысячи подобных… Почесть, деньги — все им мало.",0,366,0,0],["v","Власти ищут, а добились — чуть доходит до расплаты,",0,367,0,0],["v","Проклинают алчность черни, будто люди виноваты,",0,368,0,0],["v","Что под царскою кольчугой сердце лани робкой бьется.",0,369,0,0],["v","Но Эллада, царь, Эллада!.. Ей за что же достается?",0,370,0,1],["v","Иль в угоду дочке царской нам отдать на посмеянье",0,370,0,0],["v","Наши славные угрозы, — этой челяди деянья",0,371,0,0],["v","Недостойные спуская? Нет, мешки вы золотые,",0,372,0,0],["v","Не годитесь вы для трона, не вожди вы боевые!",0,373,0,0],["v","Разум нужен править войском, править гражданами — ум,",0,374,0,0],["v","И, за деньги власть купивши, промахнешься, толстосум!",0,375,0,0],["sp","Корифей"],["v","Ох, не к добру, когда заспорят братья,",0,376,0,0],["v","И этот спор вражду меж них родит…",0,377,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Я браниться не намерен; краток речью, сердцем сдержан,",0,378,0,0],["v","Благородный муж так нагло в словопреньях не взирает…",0,379,0,0],["v","В брате будет чтить он брата, как бы ни был им рассержен.",0,380,0,1],["v","Посмотри, на что похож ты: горло гнев тебе спирает,",0,380,0,0],["v","Глаз белки налились кровью; что, скажи, с тобою сталось?",0,381,0,0],["v","Ты обижен? Ты ограблен? Жен для ложа не осталось?",0,382,0,0],["v","Иль за это мы в ответе, что тебе приобретений",0,383,0,0],["v","Воротить твоих не можем… мужа-сторожа Елене.",0,383,0,0],["v","В гордом брате жажда славы раздражает <span class=\"ch\" data-ch=\"menelay\">Менелая</span>:",0,384,0,0],["v","Он бывает счастлив, только жен красивых обнимая;",0,385,0,0],["v","Доблесть он считает шуткой; честь и ум ему — забава.",0,386,0,0],["v","О спартанец, пошлость вкусов обличает низость нрава…",0,386,0,0],["v","Брата ты зовешь безумцем, оттого что он решился",0,387,0,0],["v","Промах сделанный исправить… Не скорей ли ты взбесился,",0,388,0,0],["v","Что, богами щедро взыскан, новый жребий свой порочишь",0,389,0,0],["v","И жену на ложе злую воротить насильно хочешь?",0,390,0,1],["v","Иль ты мнишь, тебе в угоду опьяненные любовью",0,390,0,0],["v","Женихи перед Тиндаром мстить тогда клялися кровью?",0,391,0,0],["v","Нет, безумец, окрыляла их небесная надежда.",0,392,0,0],["v","Что ж? Веди их! Только б после не раскаяться, невежда:",0,393,0,0],["v","Бог не дремлет и не слепнет, и ему всегда известно,",0,394,0,0],["v","Если вынудили клятву без сознанья и бесчестно…",0,395,0,0],["sd","Движение у <span class=\"ch\" data-ch=\"menelay\">Менелая</span>."],["v","На меня ж не полагайся… Не зарежу голубицы,",0,396,0,0],["v","И тебе я — не помощник в исправлении блудницы,",0,397,0,0],["v","Чтобы мужа утешала, оставляя мне на долю",0,398,0,0],["v","Над пролитой детской кровью дни и ночи плакать вволю!",0,399,0,0],["v","Все сказал тебе, Атрид, я речью краткой и прямою.",0,400,0,1],["v","Вразумил — тебе же лучше. Нет — и сам дела устрою.",0,401,0,0],["sp","Корифей"],["v","Да, речь иную нам пришлось услышать.",0,402,0,0],["v","Мы за него: спасая дочь, он прав.",0,403,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","О, горе мне! В друзьях я ошибался.",0,404,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Ища сгубить, ты их теряешь сам…",0,405,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Один отец родил нас? Не поверю!",0,406,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Разумному я брат, безумцу — нет.",0,407,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Но ведь друзей роднить должна невзгода..",0,408,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Нас друг зовет на пир, а не на казнь.",0,409,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Итак, трудов с Элладой ты не делишь?",0,410,0,1],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Да, не делю: с тобою заодно",0,410,0,0],["v","Ее какой-то демон обезумил.",0,411,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Тебя же жезл ахейский ослепил…",0,411,0,0],["v","Ступай, предатель братний… Я иные",0,412,0,0],["v","Пособия придумаю, друзей",0,413,0,0],["v","Найду иных!",0,413,0,0],["scene","Явление четвертое","s5",2,5],["v","Те же и вестник (справа).",0,414,0,0],["sp","Вестник"],["sd","О вождь союзных ратей, Привет тебе и радость! Дева-дочь,"],["v","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span> побледнел и пошатнулся.",0,415,0,0],["v","Которую в чертоге ты изволил",0,415,0,0],["v","Царевной <span class=\"ch\" data-ch=\"ifigeniya\">Ифигенией</span> назвать,",0,416,0,0],["v","Здесь, у тебя, а с ней и <span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>,",0,416,0,0],["v","Твоя супруга славная, и сын,",0,417,0,0],["v","Дитя Орест, к Атриду с ним прибыл,",0,418,0,0],["v","Так много дней не зревшему свой дом;",0,418,0,0],["v","Но женщин, царь, измаяла дорога, —",0,419,0,0],["v","У светлого источника они",0,420,0,1],["v","Остановились, с нежных ног истому",0,420,0,0],["v","Стряхнуть и кожу влагой освежить…",0,421,0,0],["v","Я кобылиц, с усталых упряжь снявши,",0,422,0,0],["v","На луг пустил: пусть травки поедят.",0,423,0,0],["v","А сам бегом к тебе. Принять с почетом",0,423,0,0],["v","Захочешь ты, конечно, мать и дочь…",0,424,0,0],["v","Ахейцы о приезде их уж знают.",0,425,0,0],["sd","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span> вздрагивает и бледнеет еще более."],["v","Да, птицей шум весь лагерь облетел:",0,426,0,0],["v","Так и бегут толпами подивиться",0,426,0,0],["v","На дочь твою, царевну… О, в миру",0,427,0,0],["v","Великие сияньем взоры манят,",0,428,0,0],["v","Что в небесах далекая звезда.",0,429,0,0],["v","Вокруг я слышал говор: \"Верно, свадьба",0,430,0,1],["v","Иль царский пир готовится… смотри,",0,430,0,0],["v","Царю-то дочь как загорелось видеть\".",0,431,0,0],["v","Другие ж прибавляли: \"Да, ее,",0,431,0,0],["v","Конечно, в храм представят Артемиде,",0,432,0,0],["v","Владычице авлидской, и алтарь",0,432,0,0],["v","Украсит ей блаженная невеста.",0,433,0,0],["v","А кто ж жених?\"",0,433,0,0],["v","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span> снимает шлем и вытирает со лба капли пота.",0,434,0,0],["v","Однако, царь, спеши!",0,435,4,0],["v","Пора, Атрид! Где ж мы возьмем кошницу?",0,435,0,0],["v","Цветов сюда!",0,436,0,0],["sd","(К <span class=\"ch\" data-ch=\"menelay\">Менелаю</span>.)"],["v","Тебе, спартанский царь,",0,436,4,0],["v","О свадебных подумать гимнах должно:",0,437,0,0],["v","Пусть брачный пир нам флейта огласит",0,437,0,0],["v","И мерные удары ног в чертоге.",0,438,0,0],["sd","Встает яркое солнце."],["v","О солнце, ты приводишь светлый день,",0,438,0,0],["v","Так пусть же он несет царевне счастье!",0,439,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Благодарю… Передохни, гонец…",0,440,0,1],["v","Бог даст, и все уладится… Оставь нас…",0,440,0,0],["v","Вестник уходит в шатер.",0,441,0,0],["scene","Явление пятое","s6",2,6],["sd","Те же, без вестника."],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","О, тяжко это новое ярмо…",0,442,0,0],["sd","(Иронически.)"],["v","Украшен им на диво царь микенский,",0,443,0,0],["v","Что демона хотел перехитрить…",0,444,0,0],["v","Им хорошо, незнатным… могут плакать,",0,445,0,0],["v","Когда хотят, и сердце в речи вылить…",0,446,0,0],["v","Стоящий наверху стыдится слез:",0,447,0,0],["v","Они его бесчестят… Гордость правит",0,448,0,0],["v","Царями, а посмотришь — так они",0,449,0,0],["v","Рабы своей же черни, да… и только…",0,450,0,1],["v","Стыд отнял у меня отраду слез,",0,450,0,0],["v","Но высушить источник слез не властен.",0,451,0,0],["v","Пред этим морем бедствий я — не царь.",0,452,0,0],["sd","(Низко поникает головой. Пауза.)"],["v","Итак, я их сейчас увижу… что ж",0,453,0,0],["v","Жене скажу?.. Как на нее глаза",0,454,0,0],["v","Дерзну поднять?.. Ее приезд нежданный",0,455,0,0],["v","Последней каплей влился в кубок бед…",0,455,0,0],["v","А между тем как было не приехать",0,456,0,0],["v","Ей с дочерью? Не всем же, как отцу,",0,457,0,0],["v","Из-под полы ребенку нож готовить:",0,458,0,0],["v","Она справлять малютку под венец",0,459,0,0],["v","Приехала… кого?.. Ифианассу,",0,460,0,1],["v","Дочь, дочь мою родную? Как не так!",0,460,0,0],["v","Аид ее, холодную, обнимет,",0,461,0,0],["v","Он ей жених… О, как мне тяжело…",0,461,0,0],["v","\"Как? Ты казнить ведешь меня, отец?",0,462,0,0],["v","Так вот он, брак обещанный! О, дай же,",0,463,0,0],["v","Дай бог тебе и всем, кого ты любишь,",0,463,0,0],["v","Всем свадьбы так же весело справлять!\"",0,464,0,0],["v","А маленький Орест?.. Ведь он увидит",0,465,0,0],["v","Смерть сестрину…",0,465,0,0],["v","Сказать-то, как дитя,",1,465,0,0],["v","Конечно, не сумеет, но понятен",0,466,0,0],["v","И страшен будет людям громкий крик",0,466,0,0],["v","Малютки безответного… Проклятье",0,467,0,0],["v","Распутнице Елене и Парису",0,468,0,0],["v","И браку их преступному проклятье!..",0,468,0,0],["sp","Корифей"],["v","Чужой жене, тебя мне все же жаль;",0,469,0,0],["v","С тобою, царь, и над тобой я плачу.",0,470,0,1],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","протягивая руку брату"],["v","Дай руку мне, и помиримся, брат.",0,470,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["dir","протягивая ему руку"],["v","Ты, вождь, сжимаешь руку горемыке.",0,471,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","В свидетели Пелопа я зову,",0,472,0,0],["v","Пелопа, деда нашего, который",0,473,0,0],["v","Отцом Атрею был: из уст моих",0,473,0,0],["v","Лукавого не выйдет слова — правду",0,474,0,0],["v","И только правду сердце через них",0,475,0,0],["v","Поведает. Когда у брата слезы",0,476,0,0],["v","Я увидал, за сердце ухватила",0,476,0,0],["v","Меня тоска — я сам готов был плакать.",0,477,0,0],["v","Беру назад слова свои — угроз,",0,478,0,0],["v","Пожалуйста, не помни и не бойся:",0,479,0,0],["v","Все муки здесь твои я пережил…",0,480,0,1],["v","О смерти <span class=\"ch\" data-ch=\"ifigeniya\">Ифигении</span> для выгод",0,480,0,0],["v","Моих прошу тебя не помышлять.",0,481,0,0],["v","Как? ты в слезах, а я — на пире буду?",0,482,0,0],["v","Нож — для твоих, и солнце — для моих?",0,482,0,0],["v","Или такой дележ потерпит Правда?..",0,483,0,0],["v","Да, наконец, чего же я ищу?",0,484,0,0],["v","Жениться вновь? Что ж, иль невест завидных",0,485,0,0],["v","Эллада мне не даст? Иль погублю",0,485,0,0],["v","В погоне за Еленою преступной",0,486,0,0],["v","Родного брата? Нет, Агамемнон,",0,487,0,0],["v","Я зла еще из рук твоих не видел.",0,487,0,0],["v","Прости ж меня, я говорил с тобой",0,488,0,0],["v","Как мальчик безрассудный, — лишь теперь",0,489,0,0],["v","Измерил я весь ужас быть убийцей",0,490,0,1],["v","Своих детей, и жалость к осужденной",0,490,0,0],["v","Глубокая вонзилась в сердце мне —",0,491,0,0],["v","Да, видно, кровь сближает нас недаром…",0,492,0,0],["v","Но что Елена ей?.. О нет, Атрид,",0,493,0,0],["v","Пускай войска уходят! Бросим этот",0,493,0,0],["v","Несчастный край! Но орошать лицо",0,494,0,0],["v","Слезами ты не должен, заставляя",0,495,0,0],["v","С собою брата плакать. Если жрец,",0,496,0,0],["v","Судьбы твоей в гадании касаясь,",0,496,0,0],["v","Затронул и мою, его слова",0,497,0,0],["v","Из памяти я вычеркнул, и снова",0,498,0,0],["v","Я для тебя — не изверг, снова — брат…",0,499,0,0],["v","Перегореть в горниле состраданья",0,500,0,1],["v","И вылиться в другую форму — мне",0,500,0,0],["v","Не стыдно, Агамемнон, нет, нисколько!..",0,501,0,0],["v","О! Я во зле не так закостенел,",0,502,0,0],["v","Чтоб надо мной права утратил разум.",0,503,0,0],["sd","⟨Корифей"],["v","Ты слово благородное сказал,",0,503,0,0],["v","Достойное Тантала, сына Зевса;",0,504,0,0],["v","Теперь ты предков оправдал своих.⟩",0,505,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Твои слова охотно похвалой",0,506,0,0],["v","Венчаю, брат, и эта перемена",0,506,0,0],["v","Вполне тебя достойна, — да, раздоры",0,507,0,0],["v","Меж братьями бывают из-за жен",0,508,0,0],["v","И жажды власти. Но на то ли, право,",0,509,0,0],["v","Судьба роднила нас, чтобы губить",0,510,0,1],["v","Друг друга мы горели?.. Но, увы,",0,510,0,0],["v","Мне больше нет возврата, и ножа",0,511,0,0],["v","От дочери я отклонить не властен…",0,512,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Что говоришь? Да кто ж велит тебе",0,513,0,0],["v","Убийцей быть тобою порожденной?",0,514,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Все войско, все ахейцы мне велят.",0,515,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Скорей тогда домой верни их, в Аргос.",0,515,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Вернуть?.. Да разве этим сбережешь?",0,516,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Ты чересчур, Атрид, боишься черни.",0,517,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","А если жрец откроет тайну им?",0,518,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Мешает жрец — смети его с дороги.",0,519,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Порода их пророчья любит честь.",0,520,0,1],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","А что их чтить? От них какая польза?",0,520,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Один еще замешанный тут есть…",0,521,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Кто там, скажи, Атрид, тебя пугает?..",0,522,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Исчадия Сисифа не забудь.",0,523,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","О, Одиссей нам повредить не может…",0,523,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Он ищет славы, брат, и он лукав.<a class=\"nr\" href=\"#n-k13\" data-n=\"k13\" aria-label=\"Примечание 13\">13</a>",0,524,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Да, это так, честолюбив он страшно.",0,525,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","И что же он? Калхантовы слова,",0,526,0,0],["v","Ты думаешь, не передаст аргосцам?",0,526,0,0],["v","А ты представь его среди толпы:",0,527,0,0],["v","Распишет им, как дочь обрек я раньше",0,528,0,0],["v","Богине на алтарь и как потом",0,529,0,0],["v","Назад сыграл. Возбуждены ахейцы,",0,530,0,1],["v","Сам знаешь, брат, и ярость их в толпе",0,530,0,0],["v","Зажечь легко. И вот по наущенью",0,531,0,0],["v","Оратора они на нас с ножом,",0,532,0,0],["v","А там и дочь не пощадят, конечно…",0,533,0,0],["v","Укроюсь ли в Киклоповых стенах —",0,534,0,0],["v","Туда придут, из-за каменьев вырвут",0,535,0,0],["v","И землю всю разграбят. Тяжело,",0,535,0,0],["v","О, тяжело… и выхода не сыщешь.",0,536,0,0],["v","Тебя прошу теперь я, <span class=\"ch\" data-ch=\"menelay\">Менелай</span>:",0,537,0,0],["v","По лагерю пройди и <span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестре</span>",0,538,0,0],["v","Не дай разведать тайны нашей… я ж",0,539,0,0],["v","Тем временем… к Аиду дочь отправлю.",0,540,0,1],["v","Менелай, плача, уходит.",0,540,0,0],["v","Не надо слез — без них довольно горя.",0,541,0,0],["sd","(Хору.)"],["v","Вы ж, чуждые, — завесу на уста…",0,542,0,0],["sd","(Уходит.)"],["scene","Первый музыкальный антракт","s7",2,7],["sp","Хор"],["str","Строфа"],["v","Благо тому, кто из чаши чар",0,543,0,0],["v","Каплю за каплей умеет пить",0,544,0,0],["v","Светлый дар Афродиты:",0,545,1,0],["v","Жало безумья не жжет его,",0,546,0,0],["v","Волны баюкают нежные,",0,547,0,0],["v","Там, где в колчане соблазнов две",0,548,0,0],["v","Бог златокудрый стрелы хранит —",0,549,0,0],["v","Ту, что блаженным навек человека творит,",0,550,0,1],["v","С той, что и сердце и жизнь отравит.",0,551,0,0],["v","Эту вторую гони от меня,",0,552,0,0],["v","Сжалься, богиня дивная!",0,553,0,0],["v","Чистого дай мне желанья жар,",0,554,0,0],["v","Негой любви упиться мне дай,",0,555,0,0],["v","Буду Киприде всегда рабой —",0,556,0,0],["v","Только с ума не своди меня.",0,557,0,0],["str","Антистрофа"],["v","Души в миру, что в лугах цветы,",0,558,0,0],["v","В пестрый ковер слились. Правды же свет",0,559,0,0],["v","Нам сияет, как солнце.",0,560,1,1],["v","Только и правде в сердцах у нас",0,561,0,0],["v","Не просиять без учения.",0,562,0,0],["v","Совесть и стыд — мудрецу венец,",0,563,0,0],["v","Сердцем стыдливый, свой долг узрев,",0,564,0,0],["v","Глаз уж потом не сведет с путеводной звезды,",0,565,0,0],["v","С бурного сердца не снимет узды:<a class=\"nr\" href=\"#n-k14\" data-n=\"k14\" aria-label=\"Примечание 14\">14</a>",0,566,0,0],["v","Дом его слава за то осенит.",0,567,0,0],["v","Сколь вы блаженны, смертные,",0,568,0,0],["v","Если вам доблесть соткала наряд:",0,569,0,0],["v","Жены, коль чистым ложе хранят,",0,570,0,1],["v","Мужи, коль град созидают свой,",0,571,0,0],["v","В тысячу рук созидают град.",0,572,0,0],["str","Эпод"],["v","О Парис, о, зачем твоя",0,573,0,0],["v","Склоны Иды покинуть душа рвалась?",0,574,0,0],["v","Любо было стадам серебристым там",0,575,0,0],["v","Пастись под музыку флейты,",0,576,0,0],["v","Там под звуки мелодий Олимпа<a class=\"nr\" href=\"#n-k15\" data-n=\"k15\" aria-label=\"Примечание 15\">15</a>",0,577,0,0],["v","Наливалось их вымя млеком…",0,578,0,0],["v","О, зачем, сияя победой,",0,579,0,0],["v","Исступила тебя богиня",0,580,0,1],["v","Снаряжать корабли в Элладу?..",0,580,0,0],["v","О, зачем пред царицыны очи",0,581,0,0],["v","В чертог, изукрашенный костью,",0,582,0,0],["v","Привела тебя страсть и, в сердце",0,583,0,0],["v","Ей вливая нежное пламя,",0,584,0,0],["v","Сам зажег ты зачем себе сердце?",0,585,0,0],["v","Не на то ли, чтоб пламя вражды теперь",0,586,0,0],["v","На твердыни Приама",0,587,0,0],["v","Гнало весла и копья Эллады?",0,588,0,0],["sd","Во время последних слов на сцену въезжает колесница; на ней <span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span> с Орестом на руках и <span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>. Орест спит."],["act","Действие второе","a3","II"],["scene","Явление шестое","s8",3,8],["v","Клитемнестра, <span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span> и Орест.",0,589,0,0],["sp","Хор"],["v","Вот они… Вот они… глядите!",0,590,0,1],["v","Слава вам, великие мира!",0,590,0,0],["v","Слава вам, венчанные счастьем!",0,591,0,0],["v","Будь здорова, моя царевна,",0,592,0,0],["v","С ней и ты, о мать <span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>,",0,593,0,0],["v","Дочь Тиндара!",0,593,0,0],["v","Слава рода твой след правит,",0,594,0,0],["v","Вся горишь ты, царица, счастьем…",0,595,0,0],["v","Вы, счастливцы, для нас, бедных, —",0,596,0,0],["v","Словно боги…",0,596,0,0],["v","Первое полухорие",0,597,3,0],["sd","(справа направляясь к <span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестре</span>)"],["v","Поспешим к колеснице, сестры,",0,598,0,0],["v","Мы царице сойти поможем,",0,599,0,0],["v","Чтоб ноги не зашибла… Нежно",0,600,0,1],["v","Берите царицу, сестры,",0,601,0,0],["v","На землю спускайте мягко.",0,602,0,0],["sd","Второе полухорие (слева направляясь к <span class=\"ch\" data-ch=\"ifigeniya\">Ифигении</span>)"],["v","А ты, царевна, не бойся…",0,603,0,0],["v","О, на празднике жданная гостья!",0,604,0,0],["sd","Женщины не решаются еще подойти к колеснице, ожидая знака царицы."],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Благодарю вас, жены, и да будет",0,605,0,0],["v","Крылатым счастьем милый ваш привет!",0,606,0,0],["v","О, я везу надежду на счастливый",0,607,0,0],["v","И добрый брак; и дочь и сын со мной…",0,610,0,1],["sd","(Слугам.)"],["v","Да выньте же невестины подарки,",0,610,0,0],["v","В шатер внести… Поосторожней, раб!",0,611,0,0],["sd","(<span class=\"ch\" data-ch=\"ifigeniya\">Ифигении</span>.)"],["v","Ты, дочь моя, спустися с колесницы",0,612,0,0],["v","Усталою и нежною стопой.",0,613,0,0],["sd","(Левому полухорию.)"],["v","Вы, женщины, в объятия царевну",0,614,0,0],["v","Примите: ей спускаться высоко.",0,615,0,0],["v","Женщины снимают <span class=\"ch\" data-ch=\"ifigeniya\">Ифигению</span>.",0,615,0,0],["v","Ну, кто-нибудь и мне подайте руку,",0,616,0,0],["sd","(правому полухорию)"],["v","Одна с колес высоких не спущусь…",0,617,0,0],["v","Правое полухорие к ней, но она останавливает их жестом.",0,618,0,0],["sd","(Слугам.)"],["v","Сперва, рабы, пред колесницей станьте…",0,619,4,0],["v","Ведь лошади пугливы… Вы ж дитя",0,620,4,1],["sd","(перед тем как спускается, передает корифею Ореста)"],["v","Возьмите, гостьи. Это наш царевич,",0,620,4,0],["v","Ребенок крошечный еще, Орест.",0,621,4,0],["sd","(К Оресту.)"],["v","Что, дитятко? Устал ты, убаюкан",0,622,4,0],["v","Повозки ходом мерным? Ничего,",0,622,4,0],["v","Я разбужу тебя, когда мы будем",0,623,4,0],["v","Сестру венчать: ты знатен, мой Орест,",0,624,4,0],["v","А станешь и еще знатней сегодня:",0,624,4,0],["v","С богиней породнишься по сестре…",0,625,4,0],["sd","Женщины правого полухория помогают ей сойти."],["sd","(Дочери.)"],["v","Ты ж, дочь моя,",0,626,2,0],["v","Стань, Ифигения, со мною рядом…",0,626,0,0],["v","Дочь подходит.",0,627,0,0],["v","О, эти гостьи, верно, мне теперь",0,628,0,0],["v","Завидуют.",0,628,0,0],["scene","Явление седьмое","s9",3,9],["sd","Те же и <span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span> (слева). Он идет медленно, опустив голову, весь вооружен и одет по-царски. За ним свита. Во время последующего разговора лицо царя бледно, губы сухие, улыбка слабая."],["v","А вот и царь… Иди же,",0,629,4,0],["v","Дитя мое, скажи ему привет…",0,630,2,1],["sd","(Делает по направлению к мужу три шага.)"],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["dir","сначала идет к ней, потом обгоняет ее и наскоро оборачиваясь"],["v","Ты, мама, не сердись, коли тебя я",0,630,0,0],["v","Перегоню… Душа горит скорей",0,631,0,0],["v","К груди отца прижаться грудью нежной.",0,632,0,0],["v","(Бежит к отцу и молча нежно его обнимает.)",0,633,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["dir","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнону</span>"],["v","О царь души моей, Агамемнон,",0,633,0,0],["v","Мы у тебя, твоей послушны воле.",0,634,0,0],["sd","(С достоинством, но низко склоняет голову.)"],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["dir","обнимая отца"],["v","Отец, любимый мой, дай раньше мне",0,635,2,0],["v","Тебя обнять, я вся горю желаньем…",0,636,2,0],["sd","(Любуясь им.)"],["v","О, милые черты!",0,636,2,0],["sd","(Обращается к матери с виноватой улыбкой.)"],["v","Прости, родная!",0,637,4,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["dir","с улыбкой"],["v","Я не сержусь, любимая моя:",0,638,0,0],["v","К отцу всегда ты всех была нежнее…",0,639,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["dir","кладет голову на грудь <span class=\"ch\" data-ch=\"agamemnon\">Агамемнона</span>"],["v","О, как теперь мне сладко наконец…",0,640,0,1],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","И мне, дитя: скажи за нас обоих.",0,640,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Как хорошо, что ты послал за мной!..",0,641,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Не знаю, Ифигения, не знаю.",0,642,0,0],["sd","Пауза."],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["dir","смотря на отца"],["v","Отец…",0,643,0,0],["v","Ты говоришь, что рад, а сам печален?",0,644,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Заботы, дочь: на то я вождь и царь.",0,645,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Побудь со мной… ты думать будешь после.",0,646,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Да я и так с тобою… весь с тобой…",0,647,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","О, прогони же тень с лица улыбкой.",0,648,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["dir","силясь улыбнуться"],["v","Дитя мое, мне весело теперь…",0,649,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Да, весело… А сам зачем же плачешь?",0,650,0,1],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Разлука нас, боюсь, надолго ждет…",0,650,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Слова твои, отец, мне непонятны…",0,651,0,0],["v","Но сердцем я… я поняла тебя.",0,652,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","О сердца ум, как ты меня терзаешь…",0,653,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["dir","складывая руки"],["v","Он замолчит, отец! но улыбнись.",0,653,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["dir","про себя"],["v","Уф! Я не в силах больше…",0,654,0,0],["sd","(<span class=\"ch\" data-ch=\"ifigeniya\">Ифигении</span>.)"],["v","Улыбаюсь…",0,655,4,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Отец, вернемся в Аргос, в наш дворец:",0,656,0,0],["v","Как рады там тебе, отец, мы будем.",0,656,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","О, если бы я смел, о, если б мог…",0,657,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Проклятье вам, война и брак Елены!",0,658,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Проклятье как кому, а мне давно…",0,659,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Как долго ты сидишь в Авлиде этой!",0,660,0,1],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Да, и теперь еще помеха есть…",0,660,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Отец, а где ж фригийский этот город?",0,661,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Там, где Парис, на горе нам, рожден…",0,662,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","И ты, меня покинув, вдаль уедешь?",0,663,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Да, жребий нас один и тот же ждет.",0,664,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Как было бы, отец мой, хорошо,",0,665,0,0],["v","Когда б меня с собою взял ты в море.",0,666,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","О, там, в волнах, отца не проклинай!<a class=\"nr\" href=\"#n-k16\" data-n=\"k16\" aria-label=\"Примечание 16\">16</a>",0,667,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","А с мамой я или одна поеду?",0,668,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Нет, без отца, без матери — одна.",0,669,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Иль новый дом ты мне, отец, готовишь?",0,670,0,1],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["dir","сдерживаясь"],["v","Оставь — девице рано это знать.",0,670,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Смотри ж: скорей вернись к нам, и с победой.",0,671,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Без жертвы, дочь, отсюда не уплыть…",0,672,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Дай посмотреть на жертву, если можно.",0,672,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","О да; о да: ты станешь у воды.<a class=\"nr\" href=\"#n-k17\" data-n=\"k17\" aria-label=\"Примечание 17\">17</a>",0,673,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","А танцевать пред алтарем мы будем?",0,674,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Ты счастлива… о, если б и отцу",0,675,0,0],["v","Не знать того, что скрыто от малютки…",0,675,0,0],["v","Но не пора ль в шатер?.. Девице быть",0,676,0,0],["v","Замеченной на улице мужами",0,677,0,0],["v","Не подобает, дочь моя. Приди",0,677,0,0],["v","И поцелуй меня.",0,678,0,0],["sd","(Целует ее.)"],["v","О, горькое лобзанье, —",0,679,4,0],["v","Руки холодное пожатие.",0,680,0,1],["v","Прощай, дитя! Увидимся ли скоро?..",0,680,0,0],["v","Простите же: ты, грудь, и вы, уста,",0,681,0,0],["v","И косы золотые… Сколько муки,",0,682,0,0],["v","О, сколько муки ожидает нас",0,682,0,0],["v","От этих стен фригийских и Елены!",0,683,0,0],["sd","(Отрываясь от прижавшейся к нему <span class=\"ch\" data-ch=\"ifigeniya\">Ифигении</span>.)"],["v","Ну, будет же, прощай… А вы зачем",0,684,0,0],["v","Из глаз моих на грудь к малютке, слезы? (Строго.)",0,684,0,0],["v","Ступай в шатер…",0,685,0,0],["v","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span> уходит, склонив голову.",0,686,0,0],["scene","Явление восьмое","s10",3,10],["sd","Те же, без <span class=\"ch\" data-ch=\"ifigeniya\">Ифигении</span>."],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["dir","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестре</span>"],["v","А ты, о Леды дочь,",0,686,4,0],["v","Не обессудь меня за эту слабость",0,687,0,0],["v","При расставанье с дочерью: ее",0,688,0,0],["v","Блаженство ждет в Пелидовом чертоге,",0,688,0,0],["v","А все ж отцу, когда он выдает",0,689,0,0],["v","Дочь из дому, печаль кусает сердце.",0,690,0,1],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Печаль твоя понятна мне, и, дочь",0,690,0,0],["v","Под звуки песни брачной провожая,",0,691,0,0],["v","Конечно, я заплачу и внимать",0,692,0,0],["v","Не стану утешеньям… Что же делать?",0,693,0,0],["v","Привычкой и забвеньем исцелит",0,694,0,0],["v","Твою тоску родительскую время…",0,695,0,0],["v","Но ты сказал мне имя жениха;",0,695,0,0],["v","Знать род его горит желаньем сердце…",0,696,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Эгину бог родил речной — Асоп.",0,697,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","А кто же мужем был ей: бог иль смертный?",0,698,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","О, сам Кронид Эаку был отцом.",0,699,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","А сын какой наследовал Эаку?",0,700,0,1],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Пелей на Нереиде был женат.",0,701,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Нерей вручил, иль он с богами спорил?",0,702,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Был сватом Зевс, а отдавал Нерей.",0,703,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","А где ж был брак? в морском его чертоге?",0,704,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","На высях Пелия, где жил тогда Хирон.",0,705,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","И где живут кентавры, по преданью?",0,706,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Да; средь богов там пировал Пелей.",0,707,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","А кем же был воспитан сын Фетиды?",0,708,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Хироном, от соблазнов вдалеке.",0,709,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","О, мудреца не выберет немудрый.",0,710,0,1],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Так вот он, зять наш будущий, каков…",0,711,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Завидный, да… Но где же трон <span class=\"ch\" data-ch=\"ahill\">Ахилла</span>?",0,712,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Во Фтии, где струится Апидан.",0,713,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","И в эту даль он увезет малютку?",0,714,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","На то ж она в его руках теперь…",0,715,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Ну, в добрый час… Когда же свадьбу справим?",0,716,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Дай полный круг Селене засветить…",0,717,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","А где же жертва брачная богине?..",0,718,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Как раз теперь ее готовлю я…",0,719,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Потом, конечно, будет пир веселый?..",0,720,0,1],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Богам сперва все должное воздам.",0,721,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","А где же мне и женам быть при этом?",0,722,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Да тут же, возле гордых кораблей…",0,723,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Коли нельзя иначе, покоримся.",0,724,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["dir","нерешительно"],["v","Жена… послушай… Только ты не спорь…",0,725,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Когда ж меня видал ты непокорной?..",0,726,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Я остаюсь… и мог бы жениху…",0,727,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Дочь передать… без матери… Отлично!",0,728,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Не одному, перед лицом дружин.",0,729,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","А матери где ж быть тогда назначишь?",0,730,0,1],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Домой вернись… Там дети у тебя.",0,731,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","И бросить дочь? Кто ж ей засветит факел?",0,732,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Я перед нею факел понесу.",0,733,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Да ни за что! Что ж это, шутки, что ли?..",0,734,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Подумай… Женщине среди солдат…",0,735,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","А дочь без матери оставить? Сам подумай.",0,736,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Другие дочери в Микенах у тебя.<a class=\"nr\" href=\"#n-k18\" data-n=\"k18\" aria-label=\"Примечание 18\">18</a>",0,737,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","О, там запоры крепки: не тревожься!",0,738,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Эй, покорись!",0,739,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Клянуся Герой, нет…",1,739,0,0],["v","Пускай ты царь; я — мать и я — хозяйка:",0,740,0,1],["v","⟨Все для невесты приготовлю я⟩",0,740,0,0],["sd","(Уходит в шатер.)"],["scene","Явление десятое","s11",3,11],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["dir","один"],["v","Еще одной надежды нет — жену",0,741,0,0],["v","Отсюда мне отправить не удастся:",0,742,0,0],["v","О, это ясно. Против близких сердцу",0,742,0,0],["v","Я замышлял коварство — и разбит",0,743,0,0],["v","Со всех сторон. Теперь мне остается",0,744,0,0],["v","К жрецу пойти и вместе обсудить",0,745,0,0],["v","Весь этот труд, столь тяжкий для Эллады",0,745,0,0],["v","И для меня столь горький, что богине",0,746,0,0],["v","Угодно было нам на долю дать…",0,747,0,0],["v","А я скажу и без гаданий: если",0,747,0,0],["v","Ты женишься, то выбирай жену",0,748,0,0],["v","И верную и добрую, чтоб дома",0,749,0,0],["v","Сидела… — или вовсе не женись.",0,750,0,1],["sd","(Уходит налево.)"],["scene","Второй музыкальный антракт","s12",3,12],["sp","Хор"],["str","Строфа I"],["v","Скоро ль к пене серебряной,",0,750,0,0],["v","На Симоентов берег,",0,751,0,0],["v","Рати Эллады, хлынете вы?",0,752,0,0],["v","Скоро ль с судов поведет вас меч",0,753,0,0],["v","На Илион фригийский,",0,754,0,0],["v","Фебов чертог старинный?",0,755,0,0],["v","Дивно сплетая там золото кос",0,756,0,0],["v","С бледной зеленью лавра,",0,757,0,0],["v","Дева Кассандра, пророчица",0,758,0,0],["v","Феба, в эфир погружает взор,",0,759,0,0],["v","Если дыханью бога внемлет.",0,760,0,1],["str","Антистрофа I"],["v","Там, забрало усеяв стен,",0,761,0,0],["v","Ужаса полны, люди",0,762,0,0],["v","В дальнее море взоры вперят…",0,763,0,0],["v","Ближе все медный Ареев щит",0,764,0,0],["v","Держат враги на Трою,",0,765,0,0],["v","К пене седой Симунта,",0,766,0,0],["v","Едут к столице Приамовой:",0,767,0,0],["v","Братьев сестру небесных,<a class=\"nr\" href=\"#n-k19\" data-n=\"k19\" aria-label=\"Примечание 19\">19</a>",0,768,0,0],["v","В Спарту Елену вернуть хотят,",0,770,0,1],["v","Дивную нивам родным отдать",0,771,0,0],["v","После упорных битв кровавых…",0,772,0,0],["str","Эпод"],["v","⟨Вперед, Атрид! Кровавой ратью",0,773,0,0],["v","Пергама каменный венец",0,774,0,0],["v","Ты окружишь; уж срыты стены,",0,775,0,0],["v","Защитники твердыни взятой",0,776,0,0],["v","Уж кровью обагряют прах.",0,777,0,0],["v","В слезах царевны молодые",0,778,0,0],["v","Сидят вкруг матери своей;",0,780,0,1],["v","В слезах и ты, что в вихре страсти",0,780,0,0],["v","Супруга бросила, — Елена,",0,781,0,0],["v","Прекрасная Зевеса дочь.⟩",0,782,0,0],["v","О, пусть не сойдут никогда ко мне,",0,783,0,0],["v","Не посетят ни детей моих",0,783,0,0],["v","Эти заботы…",0,784,0,0],["v","Внукам моим их вовсе не знать,",0,785,0,0],["v","Что истерзают вас,",0,786,0,0],["v","Лидии жены и Фригии,",0,786,0,0],["v","Раззолоченные…",0,787,0,0],["v","Будете возле станков своих",0,788,0,0],["v","Так причитать, тоскуя, вы:",0,789,0,0],["v","\"Кто с моих кос умащенных фату сорвет,",0,790,0,1],["v","Кто от погибших родимых стен",0,790,0,0],["v","Вдаль умчит меня силою,",0,791,0,0],["v","Всю слезами залитую?",0,792,0,0],["v","Дочь долговыйного лебедя,",0,793,0,0],["v","Ты меня губишь, ты!",0,794,0,0],["v","Если не лжет молва,",0,795,0,0],["v","Что родила тебя Леда",0,796,0,0],["v","Зевсу, принявшему птичий вид;",0,797,0,0],["v","Если все это не сказки,",0,798,0,0],["v","Что неправду по свету",0,799,0,0],["v","Сеют из книг поэтов\".",0,800,0,1],["act","Действие третье","a4","III"],["scene","Явление одиннадцатое","s13",4,13],["v","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span> и стража <span class=\"ch\" data-ch=\"agamemnon\">Агамемнона</span>.<a class=\"nr\" href=\"#n-k20\" data-n=\"k20\" aria-label=\"Примечание 20\">20</a>",0,800,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["dir","подходя к шатру"],["v","Союзных ратей вождь, Агамемнон…",0,801,0,0],["sd","(Одному из стражи.)"],["v","Скажи царю, слуга, что сын Пелея",0,802,0,0],["v","С ним хочет говорить… Я буду ждать.",0,803,0,0],["sd","Страж уходит."],["v","Да, на брегах Еврипа нас немало",0,803,0,0],["v","Народу ждет… И ждать не всем легко:",0,804,0,0],["v","Одни из нас, разбивших здесь палатки,",0,805,0,0],["v","Холостяки — за ними дом пустой…",0,806,0,0],["v","А каково женатым и семейным?..",0,806,0,0],["v","Уж подлинно не без богов тогда",0,807,0,0],["v","Безумный пыл объял сердца ахейцев.",0,808,0,0],["v","Царю сказать пришел я про своих:",0,809,0,0],["v","Таков мой долг. Пускай потом другие",0,810,0,1],["v","С меня пример берут, коли хотят…",0,810,0,0],["v","Из дома отчего и из Фарсала",0,811,0,0],["v","Родимого к чуть плещущей волне",0,812,0,0],["v","Еврипа я привел свои дружины,",0,812,0,0],["v","И их мне на узде теперь держать",0,813,0,0],["v","Приходится. Что день, то все грознее",0,814,0,0],["v","Ко мне мои солдаты пристают:",0,815,0,0],["v","\"Скажи, Ахилл, чего ж мы ждем в Авлиде?",0,815,0,0],["v","Придется ли отплыть нам в Илион?",0,816,0,0],["v","За дело, царь! А если нет работы,",0,817,0,0],["v","Назад, домой веди! Мы не хотим",0,817,0,0],["v","На дремлющих Атридов любоваться!\"",0,818,0,0],["scene","Явление двенадцатое","s14",4,14],["sd","Из шатра выходит богато разодетая и пышно причесанная <span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>."],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","О чадо Нереиды, голос твой<a class=\"nr\" href=\"#n-k21\" data-n=\"k21\" aria-label=\"Примечание 21\">21</a>",0,819,0,0],["v","Я из шатра услышала… Ну, здравствуй…",0,820,0,1],["sd","(Делает к нему шаг.)"],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["dir","отступая в изумлении"],["v","О, стыд!.. О, боги!.. Предо мной жена",0,821,0,0],["v","Блестящая и дивная красою…",0,822,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Друг друга мы не знали, о Пелид,",0,823,0,0],["v","Но скромностью твоею я любуюсь…",0,824,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Кто ты, жена? И как среди щитов",0,825,0,0],["v","Ты, слабая, проникла в этот лагерь?",0,826,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Дочь Леды, Клитемнестра, пред тобой:",0,827,0,0],["v","Ее супруг — державный <span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>.",0,828,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Немного слов — а сколько блеска в них…",0,829,0,0],["v","Но с женщиной беседа мне зазорна…",0,830,0,1],["sd","(Хочет уйти.)"],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Куда же ты? Дай руку мне пожать",0,830,0,0],["v","Десницею в залог счастливой свадьбы!",0,831,0,0],["sd","(Протягивает руку.)"],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["dir","отдергивает свою"],["v","Что говоришь?.. Мне оскорбить царя,",0,832,0,0],["v","Рукой его касаяся святыни?",0,833,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Ты не чужой, ты дочери моей",0,834,0,0],["v","Жених, о сын богини Нереиды!",0,835,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["dir","в изумлении"],["v","Жених? В устах остановилась речь,",0,836,0,0],["v","Безумную сейчас я слушал сказку!",0,837,0,0],["sd","Пауза."],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","О, это так понятно: ты друзей",0,838,0,0],["v","Еще стыдишься новых; если брака",0,839,0,0],["v","Коснется речь, ты должен покраснеть…",0,840,0,1],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Да что с тобой? Ни я не думал сватать",0,840,0,0],["v","Твоей царевны, женщина, ни мне",0,841,0,0],["v","Ее Атрид не предлагал в невесты…",0,842,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["dir","в раздумье, с расстановкой"],["v","Ты удивлен… Дивись же вновь, Пелид.",0,843,0,0],["sd","(Понизив голос.)"],["v","Ты… ты сразил меня своим признаньем!",0,844,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Задача для обоих… Оба мы",0,845,0,0],["v","Обмануты, царица… Не ошибка ль?",0,846,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["dir","отступая и закрывая лицо руками"],["v","Какой позор… Я в небывалый брак",0,847,0,0],["v","Поверила… О, боги, как мне стыдно…",0,848,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Э, стоит ли все к сердцу принимать;",0,849,0,0],["v","Смотри: делю твой жребий и — спокоен…",0,850,0,1],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["dir","отнимает от лица руки и склоняет лицо от стыда"],["v","Прости… Очей поднять перед тобой",0,850,0,0],["v","Не смею я, осмеянная лгунья…",0,851,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Прости и ты, царица, и не плачь…",0,852,0,0],["v","А я пойду искать <span class=\"ch\" data-ch=\"agamemnon\">Агамемнона</span>.",0,853,0,0],["sd","Оба хотят уйти: <span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span> в шатер, <span class=\"ch\" data-ch=\"ahill\">Ахилл</span> налево — в лагерь."],["scene","Явление тринадцатое","s15",4,15],["v","Те же и старый раб (сначала за сценой в шатре).",0,854,0,0],["sp","Голос старого раба"],["dir","тихо"],["v","Преклони, внимая, ухо, чадо славной Нереиды,",0,855,0,0],["v","О, внимай и ты, царица, Зевса дочь и чадо Леды!",0,856,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Кто там голосом дрожащим из-за двери нас зовет?",0,857,0,0],["sp","Голос старого раба"],["v","Старый раб, гордиться нечем — чем родился, тем умрет.",0,858,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Раб, а чей? Не мой, конечно. Нам с Атридом не делиться.",0,859,0,0],["sp","Голос старого раба"],["v","Я — Тиндаров, и в Микены привезла меня царица.",0,860,0,1],["sd","(Приотворяет дверь.)"],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Дальше что? Коль только это ты сказать хотел, прощай!",0,861,0,0],["sd","Голос (таинственно)"],["v","Вы одни здесь подле двери? Оглядись и отвечай.",0,862,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Мы — одни: иди же смело за порог палат хранимых…",0,863,0,0],["sp","Старик"],["dir","входя, поднимает руки к небу"],["v","О судьба и опыт старца! Дайте мне спасти любимых!",0,864,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Речь ведет он о грядущем. Но угроза в ней звучит.",0,865,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","О, молю тебя, не медли. Тайна сердце мне томит.",0,866,0,0],["sp","Старик"],["v","Я ль тебе и детям царским верой-правдой не старался?",0,867,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Помню, помню, старец верный, ты всегда таким казался.",0,868,0,0],["sp","Старик"],["v","К <span class=\"ch\" data-ch=\"agamemnon\">Агамемнону</span> с приданым я невестиным попал.",0,869,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Да, со мной ты в Аргос прибыл: муж тебя не покупал…",0,870,0,1],["sp","Старик"],["v","Оттого и сердцем предан я тебе, а не царю…",0,871,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["dir","нетерпеливо"],["v","Тайну мне, скорее тайну! Брось все это, говорю.",0,872,0,0],["sp","Старик"],["v","Так узнай же: царь-родитель дочь свою убить собрался.",0,873,0,0],["sd","Движение у <span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестры</span>. Внимание у <span class=\"ch\" data-ch=\"ahill\">Ахилла</span>."],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Что такое? Бредишь, старый? Ты… Ты просто помешался…",0,874,0,0],["sp","Старик"],["dir","всхлипывая"],["v","Шею белую малютке царский нож его пронзит!",0,875,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Горе, горе мне!.. Безумьем занедужил царь Атрид…",0,876,0,0],["sp","Старик"],["v","Ум его здоров для прочих… Для своей семьи хворает…",0,877,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Но какой же демон сердцем <span class=\"ch\" data-ch=\"agamemnon\">Агамемнона</span> играет?",0,878,0,0],["sd","Старик Тот, что рек через Калханта: уготовьте кровью путь."],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Путь? Героям чрез девичью кровью залитую грудь?..",0,880,0,1],["sp","Старик"],["v","Путь к чертогам Дарданидов за спартанскою царицей…",0,881,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Как? Елену выкупают кровью этой голубицы?",0,882,0,0],["sp","Старик"],["v","Царь-отец перед богиней заколоть ее готов.",0,883,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["dir","к <span class=\"ch\" data-ch=\"ahill\">Ахиллу</span>"],["v","И придумал брак, чтоб вызвать нас из царских теремов?",0,884,0,0],["sp","Старик"],["v","Да, царица, брак с <span class=\"ch\" data-ch=\"ahill\">Ахиллом</span> в самом деле брак завидный.",0,885,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","О дитя мое, на горе мы с тобой спешили, видно…",0,886,0,0],["sp","Старик"],["v","Плачь, царица, плачь, царевна: дерзок страшный грех отца.",0,887,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["dir","плачет"],["v","Силы нет… О, лейтесь, слезы, лейтесь с белого лица!..",0,888,0,0],["sp","Старик"],["v","Плачь… слезами не оплачешь ты родного мертвеца.",0,889,0,0],["sd","Пауза."],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Как же ты проведал, старец, про несчастье наше злое?..",0,890,0,1],["sp","Старик"],["v","Царь, взамен письма, со мною посылал тебе другое…",0,890,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","С приказаньем иль с отказом <span class=\"ch\" data-ch=\"ifigeniya\">Ифигению</span> везти?",0,891,0,0],["sp","Старик"],["v","О, с отказом: он в то время на благом стоял пути…",0,892,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Где ж письмо? Зачем не отдал ты тогда его мне в руки?",0,893,0,0],["sp","Старик"],["v","<span class=\"ch\" data-ch=\"menelay\">Менелай</span> меня ограбил — вот виновник вашей муки…",0,894,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Чадо дивной Нереиды, ты внимал ли нам, Пелид?",0,895,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Да, тебя мне жаль. Обида гневом сердце мне палит.",0,896,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Брак твой выдуман, чтоб легче здесь зарезать им малютку.",0,897,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Но недешево заплатит царь Атрид за эту шутку.",0,898,0,0],["sd","(Указывает рабу на выход. Тот уходит.)"],["scene","Явление четырнадцатое","s16",4,16],["v","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span> и <span class=\"ch\" data-ch=\"ahill\">Ахилл</span>.",0,899,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["dir","бросаясь к ногам <span class=\"ch\" data-ch=\"ahill\">Ахилла</span>"],["v","О, внемли моим моленьям, смертный сын богини дивной,",0,900,0,1],["v","Посмотри, о, мне не стыдно обнимать твои колени,",0,900,0,0],["v","Эту царскую гордыню я топчу перед тобою,",0,901,0,0],["v","За спасение ребенка мать свой сан приносит в жертву…",0,902,0,0],["v","Над моею долей горькой сжалься, чадо Нереиды,",0,903,0,0],["v","Пожалей о той, носившей имя славное <span class=\"ch\" data-ch=\"ahill\">Ахилла</span>,",0,904,0,0],["v","Пусть без права, пусть на горе, все ж она его носила…",0,905,0,0],["v","Для тебя ее одела, для тебя везла в Авлиду,",0,905,0,0],["v","Чтоб прияло ложе брака трепетавшую голубку…",0,906,0,0],["v","О, позор… О, неужели ж ты отдашь ее убийцам?",0,907,0,0],["v","Нет? Не правда ль? Заклинаю и щекою, и десницей,",0,908,0,0],["v","Материнскою любовью, честью имени, которым",0,909,0,0],["v","В западню нас заманили, истерзали, убивают…",0,910,1,1],["sd","(Садясь у ног его, тихо.)"],["v","У царицы <span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестры</span> нет прибежища на свете,",0,910,0,0],["v","Кроме праха ног <span class=\"ch\" data-ch=\"ahill\">Ахилла</span> — а над ней с ножом безумец…",0,911,0,0],["v","А вокруг нее — солдаты: гордость родины и слава, —",0,912,0,0],["v","Но для женщин слабосильных страшны жесткие их руки…",0,913,0,0],["v","Если ты подашь мне помощь — спасена; откажешь — гибну…",0,914,0,0],["sp","Корифей"],["v","О муки материнства: в вас любовь,",0,915,0,0],["v","В вас и печаль, и жертвы за ребенка!",0,916,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Мой дух мечтой высокой напоен,",0,917,0,0],["v","И, горести людские понимая,",0,918,0,0],["v","Он спесь удач не ценит. Сердце мне",0,919,0,0],["v","Умеренно волнуют и печали",0,920,0,1],["v","И радости… Расчет, простой расчет",0,920,0,0],["v","Нас убедит, что лучший вождь — рассудок,",0,921,0,0],["v","Да, это он порой нам говорит:",0,922,0,0],["v","«Не размышляй — так лучше, надо делать».",0,923,0,0],["v","Порою же трудом измучит ум…",0,924,0,0],["v","На высях гор благочестивый муж",0,925,0,0],["v","Меня взрастил в немом повиновенье,",0,926,0,0],["v","И я умею слушаться. Пока",0,927,0,0],["v","Атриды нас вели ко благу, первый",0,928,0,0],["v","Я был за них… Но злому — я не раб,",0,929,0,0],["v","Свободным быть и в Трое я сумею,",0,930,0,1],["v","И вольная не задрожит рука",0,930,0,0],["v","Венцом побед увить алтарь Арею.",0,931,0,0],["sd","(<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестре</span>.)"],["v","Ты, бедная, из самых близких рук",0,932,0,0],["v","Приявшая страданье, сколько хватит",0,932,0,0],["v","В деснице сил и в сердце сожаленья,",0,933,0,0],["v","Я все отдам тебе, и дочь твоя",0,934,0,0],["v","Зарезана у кораблей не будет…",0,934,0,0],["sd","(Поднимает <span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестру</span>.)"],["v","Игру свою Атрид мне показал,",0,935,0,0],["v","Я понимаю хорошо, что имя",0,936,0,0],["v","Мое он сплел с убийством неразрывно,",0,936,0,0],["v","Чтобы убийцей всякий мог назвать",0,937,0,0],["v","Пелида, пусть ножа он не касался…",0,938,0,0],["sd","(Иронически.)"],["v","О да! во всем виновен он, Атрид;",0,938,0,0],["v","Но и <span class=\"ch\" data-ch=\"ahill\">Ахилл</span> останется ли чистым,",0,939,0,0],["v","Когда к нему прибывшую на брак",0,940,0,1],["v","В его глазах заколют… О, царевна",0,940,0,0],["v","Несчастная!.. Вообразить себе",0,941,0,0],["v","Весь этот стыд и муки! Грустный жребий!",0,942,0,0],["v","Я был бы самый жалкий из мужей,",0,943,0,0],["v","Червяк, ничто, и ниже <span class=\"ch\" data-ch=\"menelay\">Менелая</span>,",0,944,0,0],["v","Я бесом был бы зачат, не Пелеем,",0,945,0,0],["v","Когда б терпел, что именем моим",0,945,0,0],["v","Играет царь, как топором разбойник.",0,946,0,0],["v","О нет!..",0,947,0,0],["sd","(Торжественно.)"],["v","Клянусь царем, вскормленным пеной вод,",0,948,0,0],["v","Отцом меня носившей Нереиды:",0,949,0,0],["v","Перста концом коснуться не дерзнет",0,950,0,1],["v","Ее одежд властитель Тиндариды,",0,950,0,0],["v","Не то пускай в сиянье процветет",0,951,0,0],["v","Сипил, гнездо, откуда Танталиды, —<a class=\"nr\" href=\"#n-k22\" data-n=\"k22\" aria-label=\"Примечание 22\">22</a>",0,952,0,0],["v","А Фтии блеск забвение пожрет!..",0,953,0,0],["v","А ты, провидец-жрец, тебе едва ли",0,954,0,0],["v","Достанется на тризне пировать:",0,955,0,0],["v","О краснобай, пусть только раз удачно",0,955,0,0],["v","Предскажет он, а сотни раз солжет,",0,956,0,0],["v","О промахах никто и не помянет…",0,957,0,0],["v","О браке ль я жалею?.. нет, невест",0,958,0,0],["v","Искать Пелид не будет, — ложа ищут",0,959,0,0],["v","Ахиллова десятки тысяч дев…",0,960,0,1],["v","Но эта дерзость <span class=\"ch\" data-ch=\"agamemnon\">Агамемнона</span>",0,960,0,0],["v","Распорядиться именем, как вещью…",0,961,0,0],["v","Иль попросить меня не мог Атрид,<a class=\"nr\" href=\"#n-k23\" data-n=\"k23\" aria-label=\"Примечание 23\">23</a>",0,962,0,0],["v","Чтоб я завлек сюда приманкой брака",0,963,0,0],["v","Царевну, дочь его. Конечно, мне",0,963,0,0],["v","Царица-мать ее без долгих споров",0,964,0,0],["v","В Авлиду бы доставила, и здесь",0,965,0,0],["v","Пелеев сын, пред волею ахейцев",0,966,0,0],["v","И пользой их склоняясь, может быть,",0,966,0,0],["v","Им отдал бы невесту сам… Добро ж,",0,967,0,0],["v","Надменные вожди, вы ни во что",0,968,0,0],["v","Не ставите Пелида!.. Этот меч",0,969,0,0],["v","Себя покажет, а покуда Троя",0,970,0,1],["v","Еще в крови не тонет, мой клинок",0,970,0,0],["v","Мне выкрасит тот дерзкий, что похитить",0,971,0,0],["v","Попробует из рук моих царевну.",0,972,0,0],["v","Послушай же, царица: ты во мне",0,972,0,0],["v","Увидела спасителя и бога —",0,973,0,0],["v","О, я не бог, но я тебя спасу.",0,974,0,0],["sp","Корифей"],["v","О царь Пелид, слова твои достойны",0,975,0,0],["v","Тебя и дивной матери твоей.",0,975,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Увы!",0,976,0,0],["v","Как трудно нам хвалой благодеянья",0,977,0,0],["v","Оплачивать! Боишься, кубок, царь,",0,977,0,0],["v","Не до краев наполнив, оскорбить вас",0,978,0,0],["v","И перелить боишься. Благородной",0,979,0,0],["v","Душе противна лесть. А здесь, Пелид,",0,980,0,1],["v","Перед тобой, мне просто стыдно плакать:",0,980,0,0],["v","Ты так далек от недугов моих.",0,981,0,0],["v","Но, гордая душа, благословенья",0,982,0,0],["v","Из материнских уст не отвергай…",0,983,0,0],["v","Дай жалости окутать ум холодный…",0,984,0,0],["v","Что я сказать тебе хотела? Да,",0,985,0,0],["v","В тебе я зятя чтила и тобою",0,986,0,0],["v","Гордилась — сон мой прерван… нет, не то…",0,987,0,0],["v","Твоей грядущей свадьбе смерть невесты",0,988,0,0],["v","Сулит печаль — остерегись, Ахилл…",0,989,0,0],["v","Но речь свою ты начал и окончил",0,990,0,1],["v","Так счастливо; малютка будет жить.",0,990,0,0],["v","А хочешь ты — она твои колени",0,991,0,0],["v","Обнимет, умоляя. Это будет",0,992,0,0],["v","Для девушки стыдливой непривычно,",0,992,0,0],["v","Но слова твоего довольно — и она",0,993,0,0],["v","Здесь пред тобой, вся розовая, снимет",0,994,0,0],["v","С лица фату? Иль, может быть, тебе",0,995,0,0],["v","Моей мольбы достаточно и в доме",0,995,0,0],["v","Остаться ей позволишь? Впрочем, стыд,",0,996,0,0],["v","Как он ни свят, всегда покорен силе…",0,997,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Нет, женщина, ни видеть дочь твою,",0,997,0,0],["v","Ни делаться предметом пересудов",0,998,0,0],["v","Толпы невежд и праздных — не хочу я.",0,999,0,0],["v","Здесь много их, досужих языков.",0,1000,0,1],["v","Молящие ж равны мне, и не нужно",0,1001,0,0],["v","Мне ваших слез. Спасенье решено.",0,1002,0,0],["v","И вот тебе торжественная клятва:",0,1003,0,0],["v","Коль это ложь и я мечу на воздух",0,1004,0,0],["v","Бессильные угрозы — пусть убьют",0,1005,0,0],["v","Меня. Спасу же вас, так на здоровье.",0,1006,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","О, дай же бог тебе побольше сил",0,1007,0,0],["v","Нам помогать, бессильным и несчастным…",0,1008,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Но выслушай, чтоб дело удалось…",0,1009,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","О, слушаю!.. Я вся — одно вниманье.",0,1010,0,1],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Попробуем уговорить отца…",0,1011,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Но он ведь трус. Не вождь, он — раб ахейский.",0,1012,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Все ж силу слов пусть борет сила слов.",0,1013,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Что пользы в том?.. А впрочем, как прикажешь…",0,1014,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Моли царя, чтоб дочь он пощадил;",0,1015,0,0],["v","Плачь перед ним, и только если властью",0,1016,0,0],["v","Речей и слез не тронешь сердца в нем,",0,1017,0,0],["v","Ищи во мне спасенья. А уступит,",0,1018,0,0],["v","Так всем нам будет лучше. Я врага",0,1019,0,0],["v","В царе не наживаю; и в народе",0,1020,0,1],["v","Себе приобретаю похвалу,",0,1020,0,0],["v","Что действовал не силой, а рассудком;",0,1021,0,0],["v","А дочь твоя останется в живых,",0,1022,0,0],["v","В спасителе, ей чуждом, не нуждаясь…",0,1023,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Благие и разумные слова!",0,1023,0,0],["v","Но если им с моим желаньем жарким",0,1024,0,0],["v","Не сбыться, царь… Где я найду тебя,",0,1025,0,0],["v","Печальная?.. Где будет мой защитник?",0,1026,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Защитник твой придет к тебе, жена,",0,1026,0,0],["v","В тяжелую минуту… Но слезами",0,1027,0,0],["v","И воплями нам лагеря не тешь.",0,1028,0,0],["v","Ты, дочь, палат отцовских славы шумной",0,1029,0,0],["v","И имени Тиндара не должна",0,1030,0,1],["v","Средь эллинов влачить на посмеянье.",0,1030,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","О, из твоей не выйду воли я…",0,1031,0,0],["v","И пусть тебе заплатят боги, если,",0,1032,0,0],["v","На радость благородным, боги есть,",0,1033,0,0],["v","А нет… Зачем тогда все эти муки?",0,1034,0,0],["v","Уходит в шатер, <span class=\"ch\" data-ch=\"ahill\">Ахилл</span> в лагерь.",0,1035,0,0],["scene","Третий музыкальный антракт","s17",4,17],["sp","Хор"],["str","Строфа"],["v","Гимном любви брачная песнь с музыкой флейт",0,1035,0,0],["v","В души гостей сладко лилась,",0,1036,1,0],["v","К пляске голос кифар манил.",0,1037,1,0],["v","Светлый",0,1038,1,0],["v","тон тростников сзывал",1,1038,0,0],["v","Славить Пелея-царя с нимфой морей.",0,1039,0,0],["v","Пелия высь златом пяты",0,1040,1,1],["v","Дрожать заставил",0,1040,1,0],["v","Муз хоровод дивнокосых,",0,1041,1,0],["v","Радуясь пиру бессмертных.",0,1042,1,0],["v","Долго",0,1043,1,0],["v","Славила там песнь Пиерид тайну любви…",0,1044,0,0],["v","Эхо",0,1045,1,0],["v","в высях терялось, и",0,1046,2,0],["v","Темный лес отзывался.",0,1047,1,0],["v","Долго",0,1048,1,0],["v","Там Ганимед, Дарданов сын,",0,1049,1,0],["v","Ложа утеха Зевсова,",0,1050,1,1],["v","В кубки златочешуйные",0,1051,1,0],["v","Пенил богам золотой нектар,",0,1052,1,0],["v","А на песчано-блестящий брег,",0,1053,1,0],["v","Цепью вияся, плясать пришли",0,1054,1,0],["v","Пятьдесят сребротелых дев,",0,1055,1,0],["v","Нерея рождение.",0,1056,1,0],["str","Антистрофа"],["v","Ели в руках, вкруг головы зелень елей;",0,1057,0,0],["v","Стуком копыт лес огласив,",0,1058,1,0],["v","Так кентавры явились пить",0,1059,1,0],["v","Кубок",0,1060,1,1],["v","Вакха с бессмертными.",1,1060,0,0],["v","Девы ж Фессалии петь славу пришли",0,1061,0,0],["v","Нимфе морей, лону звезды,",0,1062,1,0],["v","Что воссияет…",0,1063,1,0],["v","Там, прорицая с Хироном,",0,1064,1,0],["v","Феб Аполлон воспрославил",0,1065,1,0],["v","Мужа,",0,1066,2,0],["v","Что Илион рушить пойдет с горстью людей…",0,1067,1,0],["v","Будет",0,1068,1,0],["v","Царство Приамово",1,1068,0,0],["v","Славной мужу наградой…",0,1070,3,1],["v","С вещих",0,1070,4,0],["v","Уст Аполлона Вакх сорвал",0,1071,0,0],["v","Речь и о том, как мать ему,",0,1072,0,0],["v","Старца морского богиня-дочь,",0,1073,0,0],["v","Дивное даст оружие.",0,1074,0,0],["v","Так небожителей дивный пир",0,1075,0,0],["v","Долго лелеял там радостью,",0,1076,0,0],["v","Так там свадьбу справлял Целей",0,1077,0,0],["v","С богиней Фетидою.<a class=\"nr\" href=\"#n-k24\" data-n=\"k24\" aria-label=\"Примечание 24\">24</a>",0,1078,0,0],["str","Эпод"],["v","Да, злополучная! войско ахейское",0,1079,0,0],["v","Горьким тебе венцом увьет",0,1080,0,1],["v","Девичьих кос золотое руно…",0,1080,0,0],["v","Словно",0,1081,2,0],["v","Пеструю лань, уберут тебя;",0,1082,0,0],["v","А вчера еще вольная",0,1083,0,0],["v","Лань в ущельях таилась гор;",0,1083,0,0],["v","Ты же не лань, дитя мое, —",0,1084,0,0],["v","Не свирель, не пастушья песнь",0,1085,0,0],["v","Ифигону лелеяла,",0,1086,0,0],["v","А палаты царицыны,",0,1086,0,0],["v","Чтоб из рода Инахова",0,1087,0,0],["v","Она мужа прияла любимого…",0,1088,0,0],["v","Нет, не помог твой молящий взор:",0,1089,0,0],["v","Розы стыда нежную предали.",0,1090,0,1],["v","В людях сила правду осилила:",0,1090,0,0],["v","Стыд им больше не свят, и друзей",0,1091,0,0],["v","Добродетель меж них не найдет.",0,1092,0,0],["v","Ты силен — так и прав, говорят,",0,1093,0,0],["v","Гнева божия злой не трепещет…",0,1094,0,0],["act","Действие четвертое","a5","IV"],["scene","Явление пятнадцатое","s18",5,18],["v","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span> (выходит из шатра, вся бледная).",0,1095,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Шатер меня томит… О, я должна",0,1096,0,0],["v","Царю сказать так много! Что же держит",0,1097,0,0],["v","Его и где?.. Несчастная малютка",0,1098,0,0],["v","Все от меня узнала: плач она",0,1099,0,0],["v","С рыданьями мешая, истерзала",0,1100,0,1],["v","Мне сердце там, в палатке. Так ее",0,1101,0,0],["v","В слезах я и оставила… Но вот он…",0,1102,0,0],["sd","(На приближающегося <span class=\"ch\" data-ch=\"agamemnon\">Агамемнона</span>.)"],["v","Вот будущий детоубийца. Скоро",0,1103,0,0],["v","Мир поразит он язвою души…",0,1104,0,0],["scene","Явление шестнадцатое","s19",5,19],["sd","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span> и <span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>. (На лице <span class=\"ch\" data-ch=\"agamemnon\">Агамемнона</span> сквозь бледность сквозит решимость, ноздри раздуваются, губы сжаты.)"],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Как счастлив я, о чадо Леды дивной,",0,1105,0,0],["v","Что говорить с тобою я могу",0,1106,0,0],["v","Без <span class=\"ch\" data-ch=\"ifigeniya\">Ифигении</span>. Невестам речи",0,1107,0,0],["v","Внимать иной совсем не подобает.",0,1108,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["dir","не без иронии"],["v","Рок угодил царю… А дальше что?",0,1109,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","А дальше… Дочь отправишь ты со мною.",0,1110,0,1],["v","Готово все для жертвы: возлиянье,",0,1110,0,0],["v","Мука и соль, что, очищенья ради,",0,1111,0,0],["v","Бросаем мы в пылающий огонь,",0,1112,0,0],["v","И телки там готовы кровью черной,",0,1112,0,0],["v","Пролитою во славу Артемиде,",0,1113,0,0],["v","Венчальный пир торжественно открыть.",0,1114,0,0],["sd","Пауза. <span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span> собирается с духом."],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","О, речь твою все назовут прекрасной…",0,1115,0,0],["v","Ну, а для дел — сам имя подберешь.",0,1115,0,0],["sd","(По направлению к шатру.)"],["v","Иди сюда, о дочь моя: ты знаешь",0,1116,0,0],["v","Все замыслы отцовские — с собой",0,1117,0,0],["v","Под пеплосом неси сюда малютку,",0,1117,0,0],["v","Ореста-брата…",0,1118,0,0],["scene","Явление семнадцатое","s20",5,20],["sd","Агамемнон, Клитемнестра, <span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>. (Из шатра вся в слезах выходит одетая невестой и разубранная <span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>. Она несет Ореста.)"],["v","Вот она, Атрид,",0,1119,3,0],["v","Вот дочь твоя покорная… Но, слушай,",0,1120,0,1],["v","Я буду за обеих говорить…",0,1120,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["dir","не слушая жены"],["v","Ты плачешь, дочь? А так еще недавно",0,1121,0,0],["v","Смеялась ты… Потуплен взор… Лицо",0,1122,0,0],["v","Ты за фатою прячешь… Что с малюткой?",0,1123,0,0],["v","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span> молча плачет.",0,1123,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Увы! Увы!",0,1124,1,0],["v","С какой беды начать? Средь этих зол",0,1125,0,0],["v","Не каждое ль покажется мне первым?",0,1126,0,0],["v","Кто в море вас, о волны, различит?",0,1126,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["dir","с деланным нетерпением"],["v","Да что такое с вами? Точно спелись…",0,1127,0,0],["v","Смущенный вид… Тревожные глаза…",0,1128,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["dir","в глаза Атриду, после краткого молчания, резко"],["v","Царь, твой ответ не посрамит Атрея.",0,1129,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["dir","стараясь попасть в ее тон"],["v","Без лишних слов, царица, твой вопрос.",0,1130,0,1],["sd","Молчание."],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["dir","раздельно, впиваясь в него глазами"],["v","Ты нашу дочь убить не собирался?",0,1130,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Га…",0,1131,0,0],["v","О, тяжкий бред… Как, как дерзнула ты?..",0,1132,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Пожалуйста, спокойнее!",0,1133,0,0],["v","Ты мне ответить должен, Агамемнон!",0,1134,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["dir","силясь улыбнуться"],["v","Вопроса жду умней из уст твоих.",0,1135,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Да или нет, скажи, да или нет!..",0,1135,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","О, рок! О, тяжкий рок! Проклятый жребий!..",0,1136,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Проклятый, да, и всем троим один.",0,1137,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Тебя-то кто ж обидел?",0,1138,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Ты ответа",1,1138,0,0],["v","Ждешь от меня?.. Иль не в своем уме?",0,1139,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","Все кончено… Она узнала тайну…",0,1140,0,1],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Да, ковы, царь, известны мне давно.",0,1140,0,0],["v","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span> закрывается гиматием и глухо стонет.",0,1141,0,0],["v","Теперь же молча ты одним стенаньем",0,1142,0,0],["v","Признался мне… И слов я не прошу…",0,1143,0,0],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["dir","поднимая голову"],["v","На что слова? Или прикажешь ложью",0,1144,0,0],["v","Бесстыдною несчастье украшать?",0,1145,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Ну, слушай же… Теперь завесы сняты:",0,1146,0,0],["v","Вы, мысли, вслух, и вы, загадки, прочь…",0,1147,0,0],["v","Ты помнишь ли тот день, когда насильем",0,1148,0,0],["v","Ты в жены взял меня, Агамемнон?..",0,1149,0,0],["v","В бою убил царь Тантала, который",0,1150,0,1],["v","Моим был первым мужем, и дитя,<a class=\"nr\" href=\"#n-k25\" data-n=\"k25\" aria-label=\"Примечание 25\">25</a>",0,1150,0,0],["v","Дитя мое от груди материнской",0,1151,0,0],["v","Он оторвал и продал, как раба!",0,1152,0,0],["v","Ты помнишь ли, как Зевсовым исчадьем",0,1152,0,0],["v","И братьями моими побежден. —",0,1153,0,0],["v","Священна мне их память, белоконных.",0,1154,0,0],["v","Ты помнишь, как убежища искал",0,1154,0,0],["v","Ты у Тиндара старого, и он",0,1155,0,0],["v","Один тебе защитой был и снова",0,1156,0,0],["v","Вручил тебе меня, твою жену…",0,1156,0,0],["v","О, согласись, Атрид, что, примиренной",0,1157,0,0],["v","За твой порог ступив, с тех самых пор",0,1158,0,0],["v","Женою я была тебе примерной…",0,1158,0,0],["v","Твой царский дом, как он процвел со мной!",0,1159,0,0],["v","Ты радостно под кров свой возвращался",0,1160,0,1],["v","И уезжал спокойный… и найти",0,1160,0,0],["v","Такую верную жену не всякий",0,1161,0,0],["v","Сумеет, царь… Нас мало — верных жен…",0,1162,0,0],["v","Трех дочерей тебе дала я раньше,",0,1163,0,0],["v","А вслед за ними сына…",0,1164,0,0],["v","Из малюток",1,1164,0,0],["v","Одной сегодня будет меньше, изверг…",0,1165,0,0],["v","Спросить тебя: зачем ей умирать?",0,1165,0,0],["v","И что в ответ придумаешь? Молчи,",0,1166,0,0],["v","Сама скажу: чтоб <span class=\"ch\" data-ch=\"menelay\">Менелай</span> Еленой",0,1167,0,0],["v","Вновь завладел… Отдать свое дитя",0,1168,0,0],["v","Распутнице на выкуп — что за прелесть!",0,1169,0,0],["v","На гнусное из гнусных променять",0,1170,0,1],["v","Клад самый драгоценный — вот находка…",0,1170,0,0],["v","А ты, скажи, подумал ли, когда",0,1171,0,0],["v","В поход уйдешь надолго ты, что будет,",0,1172,0,0],["v","Что будет с сердцем матери ребенка,",0,1172,0,0],["v","Которого зарежешь ты, Атрид?..",0,1173,0,0],["v","Как эта мать на ложе мертвой птички",0,1174,0,0],["v","Осуждена глядеть и на гнездо",0,1175,0,0],["v","Пустое дни за днями, одиноко",0,1175,0,0],["v","Глядеть, и плакать, и припоминать,",0,1176,0,0],["v","И повторять всечасно: \"О малютка,",0,1177,0,0],["v","Отец тебя убил, не кто другой\".",0,1177,0,0],["v","Скажи, Атрид, ты разве не боишься",0,1178,0,0],["v","Расплаты? Ведь ничтожный повод, и",0,1179,0,0],["v","Там, в Аргосе, в кругу осиротелых",0,1180,0,1],["v","Сестер ее и матери — тебя",0,1180,0,0],["v","Прием, достойный дела, встретить может…",0,1181,0,0],["v","О нет, богами заклинаю, царь,",0,1182,0,0],["v","Не зарождай виною злодеянья!..",0,1183,0,0],["v","«Я жрец, — ты говоришь, — а не палач».",0,1183,0,0],["v","Жрец, а какой, скажи, Атрид, молитвой",0,1184,0,0],["v","Благословенье призывать на нож",0,1185,0,0],["v","Ты думаешь, подъятый на ребенка,",0,1186,0,0],["v","На плоть и кровь свою, Агамемнон?",0,1186,0,0],["v","А я? могла бы я с тобой молиться?",0,1187,0,0],["v","С убийцею и за убийцу — нет!",0,1188,0,0],["v","И если б бог, малютку пожирая,",0,1189,0,0],["v","От матери еще молитвы ждал,",0,1190,0,1],["v","Он был бы глуп… Но дальше, царь, вернувшись",0,1190,0,0],["v","Домой, ужель ты б мог ласкать детей?",0,1191,0,0],["v","О, ты бы не решился! Да ребенок",0,1192,0,0],["v","Не захотел бы ни один глядеть",0,1193,0,0],["v","На этого жреца их детской крови…",0,1194,0,0],["v","Ты это взвесил? Или жезл один",0,1195,0,0],["v","В уме держал да в сердце жажду чести?",0,1195,0,0],["v","Вот что сказал бы в войске правый муж:",0,1196,0,0],["v","\"Коль парусам ахейским ветер нужен,",0,1197,0,0],["v","Пусть жребий нам укажет жертву-дочь!\"<a class=\"nr\" href=\"#n-k26\" data-n=\"k26\" aria-label=\"Примечание 26\">26</a>",0,1198,0,0],["v","И было бы то истиной. Зачем же",0,1199,0,0],["v","Других детей спасать, казня своих?",0,1200,0,1],["v","А если уж на то пошло, Елену",0,1201,0,0],["v","Спартанский царь мог дочерью купить.",0,1202,0,0],["v","Я, верная, должна терять ребенка,",0,1203,0,0],["v","Чтоб в терему распутнице сберечь",0,1204,0,0],["v","Ее дитя?.. На это, если можешь,",0,1205,0,0],["v","Ответь, Атрид… Но только это — правда;",0,1206,0,0],["v","А если правда, так подальше нож,",0,1207,0,0],["v","И дочери родной, отец, не трогай!",0,1208,0,0],["sp","Корифей"],["v","Послушайся ее, Агамемнон,",0,1209,0,0],["v","И береги детей: и все так скажут.",0,1210,0,1],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Волшебных уст Орфея не дано,",0,1210,0,0],["v","Родной мой, дочери твоей, чтоб свиту",0,1211,0,0],["v","Из камней делать и искусной речью",0,1212,0,0],["v","Сердца людей разнеживать… Тогда",0,1212,0,0],["v","Я говорить бы стала; но природа",0,1213,0,0],["v","Судила мне одно искусство — слезы,",0,1214,0,0],["v","И этот дар тебе я приношу…",0,1215,0,0],["v","Я здесь, отец, у ног твоих, как ветка,",0,1215,0,0],["v","Молящих дар; такая ж, как она,",0,1216,0,0],["v","Я хрупкая, но рождена тобою…",0,1217,0,0],["v","О, не губи ж меня безвременно! Глядеть",0,1217,0,0],["v","На божий мир так сладко и спускаться",0,1218,0,0],["v","В подземный мир так страшно, — пощади!",0,1219,0,0],["v","Я первая тебе сказала «папа»,",0,1220,0,1],["v","И ты мне первой — «дочка». Помнишь, я",0,1220,0,0],["v","К тебе взбиралась на колени с лаской?",0,1221,0,0],["v","О, как ты сам тогда меня ласкал!",0,1222,0,0],["v","Ты говорил: \"Увижу ль я, малютка,",0,1223,0,0],["v","Счастливою женой тебя? цвети,",0,1224,0,0],["v","Дитя мое, на гордость нам, Атридам!\"",0,1225,0,0],["v","А я в ответ, вот как теперь, твоих",0,1226,0,0],["v","Касаясь щек: \"О, если б дали боги",0,1227,0,0],["v","Тебя, отец, когда ты будешь стар,",0,1228,0,0],["v","В дому своем мне нежить, вспоминая,",0,1229,0,0],["v","Как ты меня, ребенка, утешал!\"",0,1230,0,1],["v","Все в памяти храню я, все словечки!",0,1230,0,0],["v","А ты забыл, ты рад меня убить…",0,1231,0,0],["v","О нет, молю тебя, тенями предков",0,1232,0,0],["v","Пелопа и Атрея заклинаю",0,1232,0,0],["v","И муками жены твоей, отец,",0,1233,0,0],["v","Моей несчастной матери, которой",0,1234,0,0],["v","Сегодня их придется испытать",0,1235,0,0],["v","Из-за меня вторично… сжалься, сжалься!..",0,1235,0,0],["v","Парисов брак!.. Елена!.. Разве ж я",0,1236,0,0],["v","Тут виновата чем-нибудь? Откуда ж",0,1237,0,0],["v","Твой приговор?",0,1237,0,0],["v","Ты сердишься, отец?",1,1237,0,0],["v","Ты не глядишь? О, если смерти надо",0,1238,0,0],["v","Меня обнять, дай унести в могилу",0,1239,0,0],["v","Наследие мое, твое лобзанье..,",0,1240,0,1],["sd","(Ласкаясь к нему, плачет.)"],["v","Ты, мой Орест, отстаивать друзей",0,1240,0,0],["v","Твоя рука еще не научилась,",0,1241,0,0],["v","Но плакать ты со мною можешь, брат,",0,1242,0,0],["v","Моли ж отца слезами, чтоб меня",0,1243,0,0],["v","Не убивал.",0,1243,0,0],["v","Когда мы в горе, дети",1,1243,0,0],["v","Не говорят, а понимают все.",0,1244,0,0],["sd","Орест плачет и ручонками трогает лицо отца."],["v","Смотри, отец, тебя без слов он молит,",0,1245,0,0],["v","Уважь мольбу и сжалься: дай мне жить!",0,1246,0,0],["v","Мы, два птенца твои, лица касаясь",0,1246,0,0],["v","Отцовского, ласкаемся к тебе:",0,1247,0,0],["v","Один — совсем малютка, я — побольше.",0,1248,0,0],["v","Что ж я еще придумаю сказать?",0,1249,0,0],["v","Для смертного отрадно видеть солнце,",0,1250,0,1],["v","А под землей так страшно… Если кто",0,1250,0,0],["v","Не хочет жить — он болен: бремя жизни,",0,1251,0,0],["v","Все муки лучше славы мертвеца.",0,1252,0,0],["sp","Корифей"],["v","Преступная Елена, сколько бедствий",0,1253,0,0],["v","Принес семье Атридовой твой брак!",0,1254,0,0],["sd","Пауза."],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["dir","твердо"],["v","Что стоит слез, что — нет, — я различаю,",0,1255,0,0],["v","Рожденных мной люблю… И ум мой цел.",0,1256,0,0],["v","Дерзать мне страшно, женщина, о, страшно!",0,1257,0,0],["v","Но не дерзнуть страшней… и… нож готов…",0,1258,0,0],["sd","(К дочери.)"],["v","Ты видишь там весь этот флот, и войско,",0,1259,0,0],["v","И меди блеск на греческих царях:",0,1260,0,1],["v","Им нет пути к твердыням Илиона",0,1260,0,0],["v","И славных стен Приама нам не взять,",0,1261,0,0],["v","Коль я, презрев богиню и провидца,",0,1262,0,0],["v","Тебя в живых оставлю, — поняла?",0,1263,0,0],["v","Что, похотью палимые, ахейцы",0,1263,0,0],["v","Вблизи своих заснувших кораблей",0,1264,0,0],["v","В мечтах казнят фригийцев, чтоб не смели",0,1265,0,0],["v","Отныне жен у греков похищать…",0,1266,0,0],["v","Там, в Аргосе, твоих сестер, пожалуй,",0,1266,0,0],["v","Они убьют, меня убьют и вас…",0,1267,0,0],["v","Коль жертвы я не принесу богине,",0,1268,0,0],["v","Презрев ее священные права.",0,1269,0,0],["v","Дитя мое… Не <span class=\"ch\" data-ch=\"menelay\">Менелая</span> волю,",0,1270,0,1],["v","Как раб, творю… Эллада мне велит",0,1270,0,0],["v","Тебя убить… ей смерть твоя угодна,",0,1271,0,0],["v","Хочу ли я иль нет, ей все равно:",0,1272,0,0],["v","О, мы с тобой ничто перед Элладой;",0,1272,0,0],["v","Но если кровь, вся наша кровь, дитя,",0,1273,0,0],["v","Нужна ее свободе, чтобы варвар",0,1274,0,0],["v","В ней не царил и не бесчестил жен,",0,1274,0,0],["v","Атрид и дочь Атрида не откажут.",0,1275,0,0],["sd","(Уходит, не глядя на женщин.)"],["scene","Явление восемнадцатое","s21",5,21],["v","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span> и <span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>.",0,1276,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","О малютка, и вы, о чужие,",0,1276,0,0],["v","Жребий казни, и ты,",0,1277,0,0],["v","О отец, уступивший Аиду дитя…",0,1278,0,0],["v",". . . . . . . . . . . . . . . .",0,1278,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","О родная, и ты, песня муки",0,1279,1,0],["v","Для обеих одна;",0,1280,1,1],["v","Этот луч в небесах — он уж больше не мой,",0,1281,0,0],["v","Это солнце погаснет…",0,1282,1,0],["v","О, увы мне, увы мне, увы!",0,1283,0,0],["v","Ты, о Иды венец снеговой,",0,1284,0,0],["v","Вы, о склоны, где плод свой нежный,",0,1285,0,0],["v","Сорвав с груди материнской,",0,1286,0,0],["v","Умирать царь Приам оставил,",0,1287,0,0],["v","Иль затем вы, о склоны, тогда",0,1288,0,0],["v","Сберегли Париса Идея,",0,1289,0,0],["v","Чтоб он Иду прославил в Трое?",0,1290,0,1],["v","О, увы мне! Зачем возрос",0,1291,0,0],["v","И средь паствы пастырем стал он",0,1292,0,0],["v","В тех зеленых лугах, где нимфы",0,1293,0,0],["v","У ключей кристальных резвятся",0,1294,0,0],["v","И для кос золотых срывают",0,1295,0,0],["v","Гиацинты и розы?..",0,1296,0,0],["v","Кто привел вас, бессмертных, туда,",0,1300,0,1],["v","Палладу с Кипридой лукавой",0,1300,0,0],["v","И Геру с послом Зевса?",0,1301,0,0],["v","О, зачем ты зажглась, вражда,",0,1302,0,0],["v","Меж Кипридой, царицею чар,",0,1303,0,0],["v","И Палладой, царицей копья,",0,1304,0,0],["v","И Герой, царя царицей?",0,1305,0,0],["v","Не красу там венчали, а смерть,",0,1306,0,0],["v","Смерть мою изрекали уста —",0,1307,0,0],["v","Слава эллинов, — имя одно",0,1308,0,0],["v","Знайте, гостьи… Богиня крови,",0,1309,0,0],["v","Крови жаждет моей, и Трои",0,1310,0,1],["v","Без нее не видать ахейцам.",0,1311,0,0],["v","Муж же тот, что меня родил, —",0,1312,0,0],["v","О мать моя, мать, —",0,1313,3,0],["v","Нет его, изменил, покинул.",0,1314,0,0],["v","О, мой жребий, о, горечь мук,",0,1315,0,0],["v","О, сиянье красы проклятой!",0,1316,0,0],["v","И у горла преступный нож,",0,1317,0,0],["v","Нож отца, что забыл про бога…",0,1318,0,0],["v","О, зачем, Авлида, скажи,",0,1319,0,0],["v","Кораблям медноклювым",0,1320,0,1],["v","Ты приют зачем открывала?",0,1320,0,0],["v","Ель кормы в заснувших водах",0,1321,0,0],["v","Им зачем, скажи, ты сковала?",0,1322,0,0],["v","Царь Зевес! Не все ли тебе",0,1323,0,0],["v","Покорны ветры, не ты ли",0,1324,0,0],["v","Смертным путь показал на восток,",0,1325,0,0],["v","На закат, и на юг, и на полночь?..",0,1326,0,0],["v","Не по воле ль твоей к нам идут",0,1327,0,0],["v","И нужда, и горе, и радость?",0,1328,0,0],["v","Не зовешь ли иного «вперед»?",0,1329,0,0],["v","Не велишь ли другому «медли»?..",0,1330,0,1],["v","Царь, зачем же сковал ты Еврип нам?",0,1331,0,0],["v","Люди, род, отцветающий за день,",0,1332,0,0],["v","Как успеете вы пережить",0,1333,0,0],["v","Все тяжкое горе и муки,",0,1334,0,0],["v","Что несет Тиндарида?..",0,1335,0,0],["sp","Корифей"],["v","Твоя судьба звучит тоскою в сердце…",0,1336,0,0],["v","О дочь моя, на то ль ты рождена?",0,1337,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Мама, воины… их много… близко к нам они, родная.",0,1338,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","О дитя! то сын богини… Для него тебя везла я…",0,1339,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Гей, рабыни, настежь двери: дальше спрячьте дочь Атрида!",0,1340,0,1],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Ты бежишь, моя малютка?",0,1340,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Мама, я стыжусь Пелида.",1,1340,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Почему же?",0,1341,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Стыдно, стыдно мне, невесте бесталанной.",0,1342,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Не до нежностей теперь нам средь напасти несказанной.",0,1343,0,0],["v","До счастливых дней отложим женский стыд и гордость сана…",0,1344,0,0],["scene","Явление девятнадцатое","s22",5,22],["v","Те же и <span class=\"ch\" data-ch=\"ahill\">Ахилл</span> (с вооруженным отрядом.)",0,1345,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","О несчастная царица, дочь Тиндара!",0,1345,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Да, Пелид.",1,1345,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Что за крики там!",0,1346,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Ты слышал? Что же, что толпа кричит?",1,1346,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Дочь твою там называют…",0,1347,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Дочь?! Ты страшен, вещий глас.",1,1347,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Там кричат: «Зарежьте деву!»",0,1348,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Все? Защиты нет у нас?",1,1348,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Сам от них едва ушел я.",0,1349,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Фессалийцу враг грозил?",1,1349,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Чуть камнями не побили…",0,1350,0,1],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Ты спасал ее, Ахилл?",1,1350,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Да.",0,1350,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Но кто же смел коснуться до тебя, богини сын?",0,1351,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Все ахейцы.",0,1352,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Разве не был ты среди своих дружин?",0,1353,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Первый враг был свой же воин.",0,1354,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","О, тогда спасенья нет.",1,1354,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Мне кричали: «Раб Атридов!»",0,1355,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Ты ж им что, Ахилл, в ответ?",1,1355,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Что невесты не отдам я.",0,1355,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Бог Пелида наставлял.",1,1355,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Сам отец ее просватал.",0,1356,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["sd","И из Аргоса призвал!.."],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Я не мог перекричать их.",0,1357,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","О, толпа, ведь это ад!",1,1357,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Все же вас я не оставлю.",0,1358,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","И ахейцы не страшат?",1,1358,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["dir","указывая на свой отряд"],["v","Видишь там людей, царица?",0,1359,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["dir","поворачиваясь к отряду"],["v","Бог вам в помощь, смельчаки!",1,1359,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Будь покойна!..",0,1360,0,1],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Сохранишь ты дочь от вражеской руки?",0,1360,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Не убьют, покуда жив я.",0,1361,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Кто ж сюда придет за ней?",1,1361,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Без числа сюда придет их, перед всеми — Одиссей.",0,1362,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Из Сисифовых?",0,1363,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Он самый.",0,1363,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Сам, или ахейцы шлют?",1,1363,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Сам своею волей царской.",0,1364,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","О палач, твой жребий лют.",1,1364,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Я смирю его.",0,1365,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Иль силой он малютку повлечет?",0,1366,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Да, за косу золотую.",0,1366,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Мать-то ты кладешь ли в счет?",1,1366,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","За нее держись…",0,1367,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","О, если б удержать ее могла я!",1,1367,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","Уцепись как можно крепче…",0,1368,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["dir","останавливая жестом разговор"],["v","Стойте… Выслушай, родная,",1,1368,0,0],["v","Все, что в сердце я скопила. На Атрида гнев напрасный",0,1369,0,0],["v","Ты оставишь. Отбиваться где уж нам с тобой, былинкам!",0,1370,0,1],["sd","(Указывая на <span class=\"ch\" data-ch=\"ahill\">Ахилла</span>.)"],["v","В муже правдою и силой нам довольно любоваться…",0,1371,0,0],["v","И его, скажи, родная, разве смеем не беречь мы?",0,1372,0,0],["v","Разве бой бесплодный стоит тех несчастий, что таит он?",0,1373,0,0],["v","О, в душе пережила я много, много, мать. Послушай:",0,1374,0,0],["v","Я умру — не надо спорить, — но пускай, по крайней мере,",0,1375,0,0],["v","Будет славной смерть царевны, без веревок и без жалоб.",0,1376,0,0],["v","На меня теперь Эллада, вся великая Эллада",0,1377,0,0],["v","Жадно смотрит; в этой жертве беззащитной и бессильной",0,1378,0,0],["v","Все для них: попутный ветер и разрушенная Троя;",0,1379,0,0],["v","За глумленье над Еленой, за нечестие Париса —",0,1380,0,1],["v","В ней и кара для фригийцев, и урок для их потомства,",0,1381,0,0],["v","Чтоб не смел надменный варвар красть замужнюю гречанку.",0,1382,0,0],["v","Умирая, я спасу вас, жены Греции; в награду",0,1383,0,0],["v","Вы меня блаженной славой, о спасенные, почтите…",0,1384,0,0],["v","А еще… Прилично ль смертной быть такой жизнелюбивой?",0,1385,0,0],["v","Разве ты меня носила для себя, а не для греков?",0,1386,0,0],["v","Иль, когда Эллада терпит и без счета мириады",0,1387,0,0],["v","Их, мужей, встает, готовых весла взять, щитом закрыться",0,1388,0,0],["v","И врага схватить за горло, а не дастся — пасть убитым,",0,1389,0,0],["v","Мне одной, за жизнь цепляясь, им мешать?.. О нет, родная,",0,1390,0,1],["v","А куда я Правду дену? Разве с истиной соспоришь?",0,1390,0,0],["v","Ну, скажи мне, разве стоит против всех аргосцев мужу",0,1391,0,0],["v","Из-за женщины сражаться! Быть убитым, может статься?",0,1392,0,0],["v","Да один ахейский воин стоит нас десятков тысяч…",0,1393,0,0],["v","Погоди… еще, родная… если я угодна в жертву",0,1394,0,0],["v","Артемиде, разве спорить мне с богиней подобает?",0,1395,0,0],["v","Что за бред!.. О, я готова… Это тело — дар отчизне.",0,1396,0,0],["v","Вы ж, аргосцы, после жертвы, сройте Трою и сожгите,",0,1397,0,0],["v","Чтобы прах ее могильный стал надолго мне курганом:",0,1398,0,0],["v","Все мое в том прахе будет: брак и дети, честь и имя…",0,1399,0,0],["v","Грек цари, а варвар гнися! Неприлично гнуться грекам",0,1400,0,1],["v","Перед варваром на троне. Мы — свободны, в Трое — челядь!",0,1401,0,0],["sp","Корифей"],["v","Твой дух высок, царевна-голубица,",0,1402,0,0],["v","Но злы они — богиня и судьба.",0,1403,0,0],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","О дочь Атрида, если бы судили",0,1404,0,0],["v","Мне брак с тобой бессмертные, то мир",0,1405,0,0],["v","Счастливцем бы украсился. Элладе",0,1406,0,0],["v","В тебе дивлюсь, тебе ж средь дев ее…",0,1407,0,0],["v","Дивлюсь словам твоим, достойным нашей",0,1408,0,0],["v","Отчизны, и теперь, когда смотрю",0,1410,0,1],["v","На благородный стан твой, то желанье",0,1410,0,0],["v","Меня пьянит — твоей руки искать,",0,1411,0,0],["v","Сберечь тебя, укрыть тебя в чертоге…",0,1412,0,0],["v","И сердце гнев — Фетидою клянусь, —",0,1412,0,0],["v","Гнев сердце мне терзает, как помыслю,",0,1413,0,0],["v","Что Одиссею я тебя отдам,",0,1414,0,0],["v","Не защитив всей силою желаний…",0,1415,0,0],["v","Подумай же: ведь умирать так страшно!..",0,1415,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Что я скажу? Иль было Тиндариды",0,1416,0,0],["v","Вам мало, чтоб сердца мужей зажечь",0,1417,0,0],["v","Любовью, и враждою, и убийством?",0,1417,0,0],["v","Что за меня вы рветесь умирать",0,1418,0,0],["v","И убивать людей? Спасти Элладу",0,1419,0,0],["v","Позволь и мне, ахеец, чем могу!",0,1420,0,1],["sp","<span class=\"ch\" data-ch=\"ahill\">Ахилл</span>"],["v","О сердце царское! Твоих решений",0,1420,0,0],["v","Коснуться не дерзаю я: в тебе",0,1421,0,0],["v","Так чисты помыслы… Но если позже",0,1422,0,0],["v","Ты передумаешь, царевна, не страдай",0,1423,0,0],["v","За то, что мне внимать не захотела…",0,1424,0,0],["v","Послушай: там, у алтаря, мои",0,1425,0,0],["v","В оружии готовы будут люди;",0,1426,0,0],["v","Когда у горла загорится нож",0,1427,0,0],["v","И у тебя невольно сердце дрогнет, —",0,1428,0,0],["v","Ты вспомнишь, что защитник твой готов.<a class=\"nr\" href=\"#n-k27\" data-n=\"k27\" aria-label=\"Примечание 27\">27</a>",0,1429,0,1],["sd","(Уходит со своим отрядом.)"],["scene","Явление двадцатое","s23",5,23],["v","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span> и <span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>.",0,1430,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","О мать, лицо твое в слезах, и ты молчишь…",0,1433,0,1],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Что ж, или мне легко все это слушать?..",0,1434,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Не размягчай мне сердца, и молю…",0,1435,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","О, говори, малютка; все исполню…",0,1436,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Волос себе в печали не стриги",0,1437,0,0],["v","И в черное не одевайся, мама.",0,1438,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Похоронив ребенка? Бог с тобой!",0,1439,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","О, не тебе над нашей славой плакать.",0,1440,0,1],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Мне траура по мертвой не носить?",0,1440,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Да ты ж меня в могилу не положишь…",0,1441,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","А как же без могилы мертвецу?",0,1442,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Могилой мне алтарь богини будет.",0,1443,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Все сделаю, малютка, как велишь…",0,1444,0,0],["v","Слова твои прекрасны…",0,1445,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Умираю",1,1445,0,0],["v","Счастливою и за Элладу, мать.",0,1446,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","А что сказать велишь, малютка, сестрам?",0,1447,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Пусть траура не носят и они.",0,1448,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Ты, может быть, пошлешь им слово ласки?",0,1449,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Пусть мне простят.",0,1450,0,1],["sd","(Оресту.)"],["v","А ты, Орест, мужай!",0,1450,4,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Да обними же брата — на него",0,1451,0,0],["v","В последний раз ты смотришь, это вспомни.",0,1452,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["dir","холодно обнимает Ореста"],["v","О милый: ты помог мне, как умел.",0,1452,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Для дома что, малютка, завещаешь?",0,1453,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["dir","подумав"],["v","Тому, кто был моим отцом, прости.",0,1454,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","О, никогда! Не раз он мне ответит.",0,1455,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Иль он убил?.. Эллада — чрез него.",0,1455,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","О нет, молчи… Обманом самым гнусным,",0,1456,0,0],["v","Свой царский сан унизив, он убил…",0,1457,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Кто ж поведет меня, пока, схватив",0,1457,0,0],["v","За косу, жрец меня не поволочит?",0,1458,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Я… я с тобой.",0,1459,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["sd","Тебе нехорошо…"],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","За пеплос уцеплюсь я.",0,1460,0,1],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Не упорствуй,",1,1460,0,0],["v","Останься здесь: так легче будет нам",0,1460,0,0],["v","Обеим. Пусть один из свиты царской",0,1461,0,0],["v","Меня на луг богини отведет,",0,1462,0,0],["v","Где жертву нож булатный ожидает.",0,1463,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Уходишь ты?",0,1464,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["sd","И без возврата, да!.."],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","От матери?",0,1465,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["sd","Но не своею волей."],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Останься, погоди…",0,1465,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Не надо слез…",1,1465,0,0],["v","А вы со мною, жены, славословьте!",0,1466,0,0],["v","И пусть пеан из ваших уст звучит,",0,1467,0,0],["v","Над смертию и тленом торжествуя…",0,1468,0,0],["v","Благословляйте греков… Из кошниц",0,1469,0,0],["v","Крупу в огонь, чтоб ярче был, бросайте…",0,1470,0,1],["v","Стой справа, мой отец, веревки прочь…<a class=\"nr\" href=\"#n-k28\" data-n=\"k28\" aria-label=\"Примечание 28\">28</a>",0,1471,0,0],["v","Во славу ей, отчизне, умираю…",0,1472,0,0],["scene","Сцена трагической пляски","s24",5,24],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["str","Строфа I"],["v","Слава тебе, богиня,",0,1473,0,0],["v","Граду Приама смерть!",0,1474,0,0],["v","Вы же смелей, о жены,",0,1475,0,0],["v","Больше цветов сюда!",0,1476,0,0],["v","Больше цветов увить мне",0,1477,0,0],["v","Кос руно золотое…",0,1478,0,0],["v","Как зачерпнете воды,",0,1479,0,0],["v","Тесным кольцом охватите",0,1480,0,1],["v","Страшный богини алтарь!..",0,1481,0,0],["v","Смоет там кровь царевны",0,1482,0,0],["v","Ужас пророческих слов.",0,1483,0,0],["v","Слава богине, слава!..",0,1484,0,0],["sp","Хор"],["str","Антистрофа I"],["v","Вот она, вот, глядите:",0,1510,0,1],["v","Смело на смерть идет…",0,1510,0,0],["v","Примет чело повязку,",0,1511,0,0],["v","Ключ оросит его,",0,1512,0,0],["v","Следом из белой шеи",0,1513,0,0],["v","Хлынет, нож обливая,",0,1514,0,0],["v","Алая кровь ее —",0,1515,0,0],["v","На грозный алтарь Артемиды.",0,1516,0,0],["v","Воду уж льет отец,",0,1517,0,0],["v","Ждет он омыть там жертву,",0,1518,0,0],["v","Крови суда там ждут,",0,1519,0,0],["v","Плыть к Илиону рады…",0,1520,0,1],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["dir","приближаясь к матери"],["str","Строфа II"],["v","Мать, о владычица-мать, пред тобою",0,1510,0,0],["v","Слезы разлуки не лью…",0,1500,0,0],["v","Жертва плакать не будет…",0,1490,0,1],["sd","(Обнимает мать, та отвечает ей машинально.)"],["v","Ио! Ио! Юницы,",0,1491,0,0],["v","Воспойте дочь Латоны,",0,1492,0,0],["v","Со мной царицу пойте,",0,1493,0,0],["v","Что здесь, перед Халкидой,",0,1494,0,0],["v","В Авлиде флот героев",0,1495,0,0],["v","Из-за меня сковала!..",0,1496,0,0],["v","Прости, земля пеласгов",0,1497,0,0],["v","Родимая; простите,",0,1498,0,0],["v","Микены, город отчий!",0,1499,0,0],["sp","Хор"],["v","Ты вспомнила город Персея,",0,1500,0,1],["v","Киклопов созданье?",0,1501,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Микены меня воспитали",0,1502,0,0],["v","На славу Эллады:",0,1503,0,0],["v","Я смертью их славлю…",0,1504,0,0],["sp","Хор"],["v","И имя твое, о, верь,",0,1505,0,0],["v","Не будет покрыто забвеньем.",0,1506,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Увы! Увы!",0,1507,3,0],["v","И ты прости, о факел дня, ты, Зевса",0,1508,3,0],["v","Сияние, иная жизнь — удел",0,1509,3,0],["v","Иной мне суждены. Прости,",0,1510,3,0],["v","О сладкое светило!..",0,1511,3,0],["sd","(Направляется к выходу в сопровождении раба.)"],["scene","Четвертый музыкальный антракт","s25",5,25],["sp","Хор"],["dir","провожая <span class=\"ch\" data-ch=\"ifigeniya\">Ифигению</span>"],["str","Антистрофа II"],["v","Воззовем к Артемиде, о жены!",0,1512,0,0],["v","Смилосердись, богиня, и, кровью",0,1513,0,0],["v","Девы чистой насытив душу,",0,1514,0,0],["v","К берегам фригийским доставь их,",0,1515,0,0],["v","К вероломным стенам Приама",0,1516,0,0],["v","Приведи данайцев, богиня!",0,1517,0,0],["v","Пусть Атрид <span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span> войску",0,1518,0,0],["v","Даст победы венец, и слава",0,1519,0,0],["v","Пусть бессмертной своей короной",0,1520,0,0],["v","Над челом у него пламенеет…",0,1530,0,1],["sd","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span> уходит. <span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>, прижимая Ореста к груди, без слез глядит ей вслед расширившимися от ужаса глазами."],["act","Действие пятое","a6","V"],["scene","Явление двадцать первое","s26",6,26],["sd","Вестник (уводивший <span class=\"ch\" data-ch=\"ifigeniya\">Ифигению</span>), потом <span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span> с Орестом из шатра."],["sp","Вестник"],["v","Тиндара дочь, царица <span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>,<a class=\"nr\" href=\"#n-k29\" data-n=\"k29\" aria-label=\"Примечание 29\">29</a>",0,1531,0,0],["v","На голос слов моих покинь шатер…<a class=\"nr\" href=\"#n-k30\" data-n=\"k30\" aria-label=\"Примечание 30\">30</a>",0,1532,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Я здесь, о раб: ты страхом и печалью",0,1533,0,0],["v","Волнуешь грудь, и в ужасе тебя",0,1534,0,0],["v","Я слушаю. Каким несчастьем новым",0,1535,0,0],["v","Ты подаришь меня?",0,1536,0,0],["sp","Вестник"],["v","Про деву-дочь",0,1537,0,0],["v","Поведать я пришел благие вести",0,1538,0,0],["v","И чудные.",0,1539,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["sd","Не медли же, гонец…"],["sp","Вестник"],["v","О госпожа, не потаю словечка, —",0,1540,0,1],["v","Вот только бы чего мне не забыть",0,1540,0,0],["v","Да языку в речах меня не спутать…",0,1541,0,0],["v","Когда твою царевну я привел",0,1542,0,0],["v","На луг расцвеченный и к роще Девы",0,1543,0,0],["v","Латонии мы подошли, немало",0,1543,0,0],["v","Там было сил ахейских, да и чернь",0,1544,0,0],["v","Толпами прибывала. Чуть завидел",0,1545,0,0],["v","Владыка <span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>, что царевна",0,1546,0,0],["v","К нему идет на жертву, как застонет!..",0,1546,0,0],["v","И голову он отвернул, чтоб дочь",0,1547,0,0],["v","Не видеть ближе; слезы побежали",0,1548,0,0],["v","Из царских глаз, но тотчас на лицо",0,1549,0,0],["v","Он надвигает плащ, а дочь-царевна",0,1550,0,1],["v","К родителю приблизилась и так",0,1550,0,0],["v","Ему сказала: \"Здесь я, царь-отец,",0,1551,0,0],["v","За родину, за всю Элладу тело",0,1552,0,0],["v","Я предаю на жертву, и никто",0,1553,0,0],["v","Меня к тому не вынуждал, — веди же",0,1554,0,0],["v","К богине дочь, коли богиня ждет.",0,1555,0,0],["v","И дай вам бог счастливую удачу,",0,1555,0,0],["v","Оружие украсить и домой",0,1556,0,0],["v","С победою вернуться из-под Трои.",0,1557,0,0],["v","А до меня ахеец ни один",0,1558,0,0],["v","Пусть не касается: я горло молча",0,1559,0,0],["v","Подставлю вам; я — сердцем не ягненок\".",0,1560,0,1],["v","Вот только и сказала, но словам",0,1560,0,0],["v","Ее тогда все шумно удивлялись:",0,1561,0,0],["v","Великою и смелою душой",0,1562,0,0],["v","Пленила всех царевна. И Талфибий-",0,1562,0,0],["v","Глашатай нас среди толпы густой",0,1563,0,0],["v","К священному молчанью призывает.",0,1564,0,0],["v","И вот Калхант-провидец вынул нож,",0,1564,0,0],["v","Что лезвие таил в суровой коже,",0,1565,0,0],["v","И в россыпь круп его он погрузил",0,1566,0,0],["v","Средь золотой корзины, а царевне",0,1566,0,0],["v","Венком чело увил. Меж тем Пелид,",0,1567,0,0],["v","Вкруг алтаря кружась, его водою",0,1568,0,0],["v","И той крупой священной окропил",0,1568,0,0],["v","И к дочери Зевесовой взывает:",0,1569,0,0],["v","\"О дивная охотница, в ночи",0,1570,0,1],["v","Ты по небу свое светило катишь…",0,1570,0,0],["v","Прими ж от войск союзных этот дар",0,1571,0,0],["v","И от вождя дружин, <span class=\"ch\" data-ch=\"agamemnon\">Агамемнона</span>:",0,1572,0,0],["v","Кровь чистую из девственной ее",0,1572,0,0],["v","И мраморной мы выпускаем шеи.",0,1573,0,0],["v","Утешься ей и даруй путь судам,",0,1574,0,0],["v","Дай Трою нам высокую разрушить!..\"",0,1574,0,0],["v","И в землю взор в молчании вперил",0,1575,0,0],["v","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>; и <span class=\"ch\" data-ch=\"menelay\">Менелай</span> и войско",0,1576,0,0],["v","Потупились. И наскоро мольбу",0,1576,0,0],["v","Жрец сотворил, меж тем как взор прилежно",0,1577,0,0],["v","На девственной груди ее искал,",0,1578,0,0],["v","Где б нож вонзить ему, чтоб без мучений",0,1578,0,0],["v","И разом ей конец настал… Вблизи",0,1579,0,0],["v","Я там стоял… Но не смотрел: мне было",0,1580,0,1],["v","Так тяжело… И вдруг…",0,1580,0,0],["v","О, из чудес",1,1580,0,0],["v","Чудесное… Я слышу скрип ножа…",0,1581,0,0],["v","Все головы приподняли невольно…",0,1582,0,0],["v","Но девушки уж не было… И первый",0,1583,0,0],["v","Заголосил провидец, и чернь ему,",0,1584,0,0],["v","Как эхо, вторила… И диво мы узрели…",0,1585,0,0],["sd","Пауза."],["v","Сам видел и не верю — на лугу,",0,1585,0,0],["v","Близ алтаря лежала, содрогаясь,",0,1586,0,0],["v","Огромная, красы отменной, лань,",0,1587,0,0],["v","И кровь ее в последних муках жизни",0,1588,0,0],["v","По ступеням рекой струилась алой…",0,1589,0,0],["v","И снова жрец воскликнул, — только крик",0,1590,0,1],["v","На этот раз был светел:",0,1591,0,0],["v","\"О ахейцы! —",1,1591,0,0],["v","Так жрец взывал, — вожди и ты, народ!",0,1592,0,0],["v","На алтаре богини перед вами",0,1593,0,0],["v","Лань горная — а благородный дар,",0,1594,0,0],["v","Царевною возданный Артемиде,",0,1595,0,0],["v","Охотницей божественной отринут…",0,1596,0,0],["v","Она довольна, греки, — ободритесь!",0,1597,0,0],["v","Смотрите: паруса вздуваются, — скорей",0,1598,0,0],["v","За дело вы, матросы, чтоб немедля,",0,1599,0,0],["v","Авлидские покинув глубины,",0,1600,0,1],["v","Нам распахать Эгейскую пучину\".",0,1600,0,0],["v","И вот, когда огонь пожрал дотла",0,1601,0,0],["v","Лань горную, жрец совершил молитву,",0,1601,0,0],["v","Да даст войскам богиня путь обратный…",0,1602,0,0],["v","Все кончилось… и господин меня",0,1603,0,0],["v","К тебе послал, царица, с вестью дивной,",0,1603,0,0],["v","Что дочь твоя среди богов удел",0,1604,0,0],["v","Днесь обрела и что молва о чуде",0,1605,0,0],["v","Меж греками, конечно, не умрет.",0,1605,0,0],["v","И сам скажу, владычица, что видел:",0,1606,0,0],["v","Была меж нас… и скрылась… Знать, богам",0,1606,0,0],["v","Ее призвать к себе угодно было.",0,1607,0,0],["v","Смири же скорбь свою и на супруга",0,1608,0,0],["v","Ты не ⟨гневись⟩. Бывает, госпожа,",0,1608,0,0],["v","Что, где совсем не ждешь спасенья, боги",0,1609,0,0],["v","Любимого спасут… А дочь твою",0,1610,0,1],["v","Сегодня солнце зрело, Клитемнестра,",0,1611,0,0],["v","Живою, мертвою и вновь узревшей свет.",0,1612,0,0],["sd","Закат солнца."],["sp","Корифей"],["v","Как радуюсь я вести этой: дева",0,1613,0,0],["v","Вкушает жизнь в обители богов.",0,1614,0,0],["sp","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span>"],["v","Дитя мое… Добычей рук бессмертных",0,1615,0,0],["v","Ты сделалась… Как призывать тебя?",0,1616,0,0],["sd","(Задумывается.)"],["v","А если это бред пустой и ложный,",0,1617,0,0],["v","Чтобы меня утешить?.. Что тогда?",0,1618,0,0],["sp","Вестник"],["v","Да вот и царь идет, о Тиндарида:",0,1619,0,0],["v","Пускай слова мои он повторит.",0,1620,0,1],["v","<span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span> остается погруженною в глубокую задумчивость.",0,1621,0,0],["scene","Явление двадцать второе","s27",6,27],["sd","Те же и <span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>."],["sp","<span class=\"ch\" data-ch=\"agamemnon\">Агамемнон</span>"],["v","О женщина… Блаженством одарила",0,1622,0,0],["v","Нас <span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>, и меж богов теперь",0,1623,0,0],["v","Она живет… А ты не медли дольше…",0,1624,0,0],["v","Дитя мое, потомка крови знатной,",0,1625,0,0],["v","Домой вези Ореста. Мы в поход",0,1626,0,0],["v","Сейчас же отплываем. Ну, простимся!",0,1627,0,0],["sd","(Делает движение к ней: <span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span> неподвижна и будто не замечает его.)"],["v","Увидимся ли скоро?.. Как-то бог",0,1628,0,0],["v","Из Трои путь обратный даст ахейцам?",0,1629,0,0],["v","Что встретит нас у очагов родных?",0,1630,0,0],["sd","(Уходит в раздумье.)"],["sd","За ним вестник, покачивая головой. <span class=\"ch\" data-ch=\"klitemnestra\">Клитемнестра</span> плачет, глядя в ту сторону, куда увели <span class=\"ch\" data-ch=\"ifigeniya\">Ифигению</span>, и прижимает к груди Ореста."],["sp","Корифей"],["dir","вслед <span class=\"ch\" data-ch=\"agamemnon\">Агамемнону</span>"],["v","О Атрид, на далеких брегах,",0,1631,0,0],["v","О, пусть дадут тебе боги",0,1632,0,0],["v","Много, много добычи фригийской,",0,1633,0,0],["v","И со славой вернись и с победой.",0,1634,0,0],["sd","Хор молча покидает сцену под звуки кларнетов и ударных инструментов, отбивающих анапесты."],["h1","Комментарий","comm"],["p","(«ИФИГЕНИЯ — ЖЕРТВА»)"],["p","Трагедия написана в Македонии после 408 г. до н.э. и поставлена посмертно в Афинах вместе с «Вакханками»."],["p","К сказанному об истории мифа во вступительной заметке к «Ифигении в Тавриде» следует здесь добавить, что известный из «Киприй» мотив мнимого сватовства Ахилла разрабатывался уже Огесихором, а затем был использован Эсхилом и Софоклом, каждый из которых написал трагедию под названием «Ифигения»; до"],["ed","В.Н. Ярхо"],["note","k1"],["note","k2"],["note","k3"],["note","k4"],["note","k5"],["note","k6"],["note","k7"],["note","k8"],["note","k9"],["note","k10"],["note","k11"],["note","k12"],["note","k13"],["note","k14"],["note","k15"],["note","k16"],["note","k17"],["note","k18"],["note","k19"],["note","k20"],["note","k21"],["note","k22"],["note","k23"],["note","k24"],["note","k25"],["note","k26"],["note","k27"],["note","k28"],["note","k29"],["note","k30"]],"n":{"k1":["Ст. 1 — 164","Единственный среди всех сохранившихся древнегреческих трагедий случай, когда вполне традиционный пролог-повествование в ямбических триметрах (ст. 49 — 114) обрамлен анапестическим диалогом Агамемнона со старым рабом (ст. 1 — 48 и 115 — 163; в переводе Анненского анапесты заменены то дольниками, то ямбами). Эту необычную для пролога форму некоторые исследователи объясняют тем, что Еврипид не успел завершить работу над трагедией, и сохранились два варианта ее начала, сведенные для первой постановки воедино. Однако ничто не мешает допустить и возможность очередного художественного эксперимента, к которым Еврипид был всегда склонен."],"k2":["Ст. 6 — 8","Сириус в небе расположен очень далеко от Плеяд; предполагается, что Еврипид по ошибке назвал Сириусом какую-то другую яркую звезду."],"k3":["Ст. 11. Еврип","узкий пролив между Беотией и Евбеей."],"k4":["Ст. 48. Провожатым почтенным невесты","Клитемнестры, выданной замуж за Агамемнона (см. ст. 50)."],"k5":["Ст. 50","Феба, старшая сестра Елены и Клитемнестры, упоминается в античной литературе только здесь (и потом у Овидия)."],"k6":["Ст. 71. Фригиец, решивший спор богинь","Парис. Фригией в древности называли страну в Малой Азии, центром которой была Троя."],"k7":["Ст. 89 — 93. …Ифигению… должен на алтаре богини заколоть.","Причину такого приказа Артемиды (см. вступит, заметку к «Ифигении в Тавриде») Еврипид здесь сознательно не объясняет: жертвоприношение Ифигении выступает в этой трагедии как патриотический акт, а не расплата за хвастовство Агамемнона."],"k8":["Ст. 114 — 123. Оглашение письма","деталь, аналогичная приему в «Ифигении в Тавриде» (ст. 769 — 787), но там она играет решающую роль в организации интриги."],"k9":["Ст. 168. Халкида","поселение и гавань на Евбее, против Авлиды. Ширина Еврипа едва достигает здесь двух километров."],"k10":["Ст. 170. Аретуса","источник близ Халкиды."],"k11":["Ст. 193 — 290","Каталогообразный перечень знаменитых участников Троянского похода, отражающий влияние как эпоса, так и вазовой живописи. Подлинность ст. 231 — 302 часто ставилась под сомнение, и Анненский оставил их без перевода; они даются в переводе Ф. Ф. Зелинского. Там двух Аяксов славных… — Первый из них, сын Оилея, вождь ополчения локров, из Средней Греции (ст. 261 — 264); другой — знаменитый саламинский герой, сын Теламона (ст. 289 — 293). Паламед, соперник Одиссея в мудрости, изобрел для томящихся ожиданием ахейцев игру в шашки; ею и заняты два Аякса и (пропущенный Анненским в переводе) Протесилай. Нирей, с малоазийского о. Симы, близ Родоса, упоминается и в гомеровском «Каталоге» («Илиада», П, 671 — 675) как молодой красавец. Ферета… внук… Евмел… — См. вступит, заметку к «Алькесте». Сын Мекистея — аргосец Евриал, ничем не замечательный; почему он назван вместо Диомеда, главного аргосского героя (по Гомеру), — неизвестно. Тесея сын — Демофонт, упоминаемый Еврипидом в «Умоляющих». Землей рожденный царь Леит — потомок «спартов» (см. вступит, заметку к «Финикиянкам»). Адраст, если это не ошибка переписчиков, попал сюда по недоразумению: он принадлежит, по мифологической генеалогии, к предшествующему поколению героев (см. «Умоляющие» Еврипида). Энианы — племя, проживавшее на границе Фессалии и Средней Греции. Остров Таф и группа островов Эхинады расположены на западе Греции, у берегов Акарнании."],"k12":["Ст. 339 — 343. …ты унижался, черни руки пожимая…","Поведение Агамемнона списано с современных Еврипиду политиканов, демагогически заискивавших перед избирателями; у Гомера ни о каких его исканиях нет и речи. В переводе Анненского эти политические мотивы еще больше подчеркнуты."],"k13":["Ст. 524. Исчадие Сисифа","Одиссей (см. примеч. к «Киклопу», ст. 104). В подлиннике сказано (ст. 526) не «ищет славы», а «заигрывает с чернью» — ср. выше, примеч. к ст. 339 — 343. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Киклоп», Ст. 104. Сисифов сын..</b> Существовала версия мифа, что Антиклея, мать Одиссея, еще до своего замужества сошлась с Сисифом, от которого и родила Одиссея; таким образом, хитрец сын получал достойного его хитреца отца.</span><!--/xn--> <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>Ст. 339 — 343. …ты унижался, черни руки пожимая….</b> Поведение Агамемнона списано с современных Еврипиду политиканов, демагогически заискивавших перед избирателями; у Гомера ни о каких его исканиях нет и речи. В переводе Анненского эти политические мотивы еще больше подчеркнуты.</span><!--/xn-->"],"k14":["Ст. 561 — 566","К спорам о врожденной или добытой ученьем мудрости см. «Гераклиды», ст. 327 сл., и примеч. к «Андромахе», ст. 766 — 776. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Андромаха», Ст. 766-776.</b> Из этих стихов не следует делать вывод, будто Еврипид защищает аристократические предрассудки о врожденной доблести. В других трагедиях мы найдем прямо противоположные высказывания. Ср. примеч. к «Гераклидам», ст. 327 сл.</span><!--/xn-->"],"k15":["Ст. 577. Олимп","фригиец, легендарный мастер игры на флейте. Флейта считалась экстатической музыкой, возбуждающей страсть, в данном случае — Парисову."],"k16":["Ст. 667. Точнее: \"Тебе","иное плавание, и ты еще вспомнишь отца\"."],"k17":["Ст. 675. Уводы","т. е. «у (жертвенных) возлияний»."],"k18":["Ст. 737. Другие дочери в Микенах у тебя.","Эпическая традиция («Илиада», IX, 145, 287) знала трех дочерей Агамемнона: Хрисофемиду, Лаодику и Ифианассу. В трагедии V в. Лаодика уступила место Электре, Ифианасса — Ифигении (ср. ст. 460, где Анненский вопреки оригиналу употребляет имя Ифианассы)."],"k19":["Ст. 769. Братьев сестру небесных","Елену, сестру Диоскуров."],"k20":["Ст. 795 — 800","Сомнение в божественном происхождении Елены (ср. «Елену», ст. 17 — 21, и примеч. к ст. 256). <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Елена», Ст. 256.</b> После этого стиха в рукописях следуют ст. 257 — 259, принятые рядом издателей за неподлинные и Анненским не переведенные: «Ведь не было случая, чтобы у эллинов или варваров женщина снесла яйцо, как говорят, родила меня Леда от Зевса». Издатели, исключающие эти стихи из текста, ссылаются на ст. 17 — 21, где Елена выражает сомнение в своем происхождении от Зевса; однако миф о рождении Елены от союза Леды с Зевсом, явившимся к ней в образе лебедя, впервые вводится в литературу как раз Еврипидом в произведениях последних лет его жизни (см. «Елена», ст. 214, 1144; «Орест», ст. 1387; «Ифигения в Авлиде», ст. 793 — 797).</span><!--/xn-->"],"k21":["Ст. 812 — 819","Мотив недовольства воинов Ахилла вынужденным бездействием есть и в «Илиаде», XVI, 202 — 206, — правда, здесь причиной является самоустранение оскорбленного Ахилла от боев."],"k22":["Ст. 952. Сипил","гора в Лидии, именем которой Еврипид называет и царство Тантала."],"k23":["Ст. 963 — 967. Иль попросить меня не мог Атрид…","Остаток ранней версии мифа, использованной, вероятно, Эсхилом и Софоклом, по которой Ахилл заранее согласился на вызов Ифигении под предлогом бракосочетания с ним и даже сам принял участие в ее жертвоприношении. Эта же версия отражена в ст. 1568 сл., Еврипиду не принадлежащих."],"k24":["Ст. 1035 — 1078","«Дифирамбический стасим»: хор вспоминает свадьбу Пелея и Фетиды. Антистрофа II переведена по устарелому тексту: вернее представлять, что пелионские кентавры принесли на пир пророчество Хирона о будущем величии Ахилла, но Аполлон и Вакх при этом не упоминались."],"k25":["Ст. 1150. …убил Тантала… который моим был первым мужем…","Этого Тантала не следует путать со знаменитым грешником, отцом Пелопа и предком Атридов; это — двоюродный брат Агамемнона, сын Фиеста, брата-врага Атрея. Об этом первом браке Клитемнестры есть сообщения, кроме Еврипида, в более поздних источниках. Возможно, что такая версия идет от Стесихора, который причину всех бед, происшедших с дочерьми Тиндарея, видел в его забывчивости: Тиндарей забыл вовремя принести жертву Афродите, и за это богиня сделала его дочерей двух- и трехмужними. Братья Клитемнестры (они же — Зевсово исчадье) — Диоскуры Кастор и Полидевк."],"k26":["Ст. 1196-1200. Пусть жребий нам укажет жертву-дочь!","Здесь, как и выше (ст. 90 сл.), Еврипид умалчивает о той версии мифа, по которой именно Агамемнон обязан был умилостивить Артемиду за свою похвальбу, — тем труднее становится положение полководца и тем очевиднее — жестокость его решения."],"k27":["Ст. 1429","После этого стиха в рукописях следует еще три, обычно исключаемые современными издателями:<br>1430. Не допущу я, чтобы неразумья<br>Ты жертвою погибла; в божий храм<br>Отправлюсь я во всеоружье этом<br>1432. И буду ждать прихода твоего.<br>(Перевод Ф. Ф. Зелинского) Эти ст. 1430 — 1432 в самом деле очень похожи на позднюю вставку, так как по содержанию они только повторяют ст. 1425 — 1428, но к тому же содержат оценку поведения Ифигении («неразумье»), несовместимую с совершаемым ею подвигом."],"k28":["Ст. 1471. Стой справа…","Точнее: «возложи на алтарь правую руку…»"],"k29":["Ст. 1521 — 1531","Антистрофа II в оригинале не дает полной ритмической симметрии к строфе II; в переводе симметрия совершенно нарушена, так как Анненским была принята ненужная перестановка текста."],"k30":["Ст. 1532 сл","Содержащийся в рукописях эксод не является творчеством Еврипида. До ст. 1578 он написан, по крайней мере, в античное время, но неумелое подражание рассказу вестника в «Гекубе» исключает авторство Еврипида; со ст. 1578 начинается сочинение византийского поэта, которого начитанность в античных авторах не избавила от множества метрических и грамматических ошибок. Подлинная еврипидовская «Ифигения» завершалась появлением Артемиды, объявляющей Клитемнестре исход жертвоприношения — перенесение Ифигении в Тавриду и подмену ее на алтаре ланью: из этого эксода сохранились четыре стиха у позднеантичного автора Элиана:<br>Ахейцам в руки я слепые лань<br>Красиворогую вложу; они же,<br>Ее зарезав, будут говорить,<br>Что дочь твою они заклали жертвой.<br>(Перевод Ф. Ф. Зелинского) Причина, по которой подлинный финал пропал и был заменен подделкой (или потому и пропал, что был заменен), неизвестна."]},"mainEnd":2597,"c":[{"id":"agamemnon","name":"Агамемнон","role":"Царь Микен, вождь ахейского войска","intro":"Отец, согласившийся принести дочь в жертву ради похода на Трою.","arc":"Агамемнон в последней трагедии Еврипида — человек, раздираемый между отцовской любовью и честолюбием. Он вызвал дочь в Авлиду обманом, будто бы для свадьбы с Ахиллом, потом раскаялся и послал второе письмо — но Менелай перехватил его. Когда Ифигения уже в лагере, Агамемнон уверяет себя, что войско не оставит ему выбора. Его встреча с женой и дочерью — мучительная игра двусмысленностей.","st":[{"i":269,"p":10,"l":"Пролог · явление первое","t":"Ночное письмо","d":"Будит старого раба и посылает его с новым письмом к Клитемнестре: не привозить дочь.","c":"Раскаяние в первом решении.","k":false},{"i":621,"p":24,"l":"Действие первое · явление третье","t":"Ссора с братом","d":"Менелай перехватил письмо; братья осыпают друг друга упрёками.","c":"","k":false},{"i":671,"p":26,"l":"Действие первое · явление четвертое","t":"Дочь прибыла","d":"Вестник сообщает, что Ифигения с матерью уже в лагере.","c":"Пути назад нет.","k":true},{"i":833,"p":32,"l":"Действие первое · явление пятое","t":"Неизбежность","d":"Менелай раскаивается и отказывается от жертвы, но Агамемнон говорит, что войско и Калхант не оставят выбора.","c":"","k":false},{"i":1085,"p":42,"l":"Действие второе · явление седьмое","t":"Встреча с дочерью","d":"Отвечает на радость Ифигении двусмысленными, полными слёз словами.","c":"","k":false},{"i":1196,"p":46,"l":"Действие второе · явление восьмое","t":"Попытка удалить жену","d":"Пытается отослать Клитемнестру домой, но она отказывается.","c":"","k":false},{"i":2016,"p":78,"l":"Действие четвертое · явление семнадцатое","t":"Разоблачён","d":"Клитемнестра и Ифигения умоляют его; он отвечает, что приносит дочь в жертву не Менелаю, а Элладе.","c":"","k":true},{"i":2596,"p":100,"l":"Действие пятое · явление двадцать второе","t":"Весть о чуде","d":"Узнаёт, что дочь взята богами, и уходит с войском.","c":"","k":false}],"gen":"Агамемнон"},{"id":"ifigeniya","name":"Ифигения","role":"Дочь Агамемнона и Клитемнестры","intro":"Девушка, вызванная в Авлиду на свадьбу, которая оказывается жертвоприношением.","arc":"Ифигения проходит самый резкий путь в пьесе: от радостной встречи с отцом через мольбу о жизни («Сладко видеть свет») к добровольному решению умереть за Элладу. Аристотель упрекал Еврипида в непоследовательности характера, но именно этот переход и составляет трагедию. Её последняя песнь — шествие к алтарю.","st":[{"i":1085,"p":42,"l":"Действие второе · явление седьмое","t":"Встреча с отцом","d":"Радостно бросается к отцу и не понимает его слёз.","c":"","k":false},{"i":2016,"p":78,"l":"Действие четвертое · явление семнадцатое","t":"Мольба","d":"Умоляет отца пощадить её: «Лучше жить в несчастье, чем умереть со славой».","c":"","k":false},{"i":2273,"p":88,"l":"Действие четвертое · явление девятнадцатое","t":"Решение","d":"Видя, что Ахилла готовы побить камнями, решает добровольно умереть за Элладу.","c":"Из жертвы — в героиню.","k":true},{"i":2366,"p":91,"l":"Действие четвертое · явление двадцатое","t":"Прощание с матерью","d":"Просит мать не носить траура и не ненавидеть отца.","c":"","k":false},{"i":2428,"p":94,"l":"Действие четвертое · Сцена трагической пляски","t":"Шествие к алтарю","d":"Ведёт хор в гимне Артемиде.","c":"","k":false},{"i":2574,"p":99,"l":"Действие пятое · явление двадцать первое","t":"Чудо","d":"Вестник рассказывает, что в миг удара она исчезла, а на её месте оказалась лань.","c":"","k":false}],"gen":"Ифигения"},{"id":"klitemnestra","name":"Клитемнестра","role":"Жена Агамемнона","intro":"Мать, привезшая дочь на свадьбу и узнавшая о жертвоприношении.","arc":"Клитемнестра здесь — гордая и любящая мать. Узнав правду, она обращается за защитой к Ахиллу и бросает мужу обвинения, которые предвещают её будущую месть.","st":[{"i":950,"p":37,"l":"Действие второе · явление шестое","t":"Прибытие","d":"Въезжает в лагерь с дочерью и маленьким Орестом.","c":"","k":false},{"i":1372,"p":53,"l":"Действие третье · явление двенадцатое","t":"Встреча с Ахиллом","d":"Приветствует его как жениха — к его недоумению.","c":"","k":false},{"i":1472,"p":57,"l":"Действие третье · явление тринадцатое","t":"Правда","d":"Старый раб открывает, что Ифигению ждёт жертвенник.","c":"Всё рушится.","k":true},{"i":2016,"p":78,"l":"Действие четвертое · явление семнадцатое","t":"Обвинение мужа","d":"Вспоминает, как Агамемнон убил её первого мужа и ребёнка, и предупреждает о мести.","c":"","k":false},{"i":2574,"p":99,"l":"Действие пятое · явление двадцать первое","t":"Весть о чуде","d":"Слушает рассказ вестника и сомневается в утешении.","c":"","k":false}],"gen":"Клитемнестра"},{"id":"ahill","name":"Ахилл","role":"Сын Пелея и Фетиды","intro":"Молодой герой, чьё имя использовали для обмана.","arc":"Ахилл возмущён тем, что его сделали приманкой. Он клянётся защитить Ифигению, но его собственные мирмидоняне восстают против него.","st":[{"i":1372,"p":53,"l":"Действие третье · явление двенадцатое","t":"Недоразумение","d":"Не понимает, почему Клитемнестра называет его женихом.","c":"","k":false},{"i":1662,"p":64,"l":"Действие третье · явление четырнадцатое","t":"Клятва","d":"Обещает защитить девушку.","c":"","k":true},{"i":2273,"p":88,"l":"Действие четвертое · явление девятнадцатое","t":"Против войска","d":"Рассказывает, что войско готово побить его камнями; готов сражаться за Ифигению.","c":"","k":false}],"gen":"Ахилл"},{"id":"menelay","name":"Менелай","role":"Царь Спарты","intro":"Брат Агамемнона, ради которого начинается поход.","arc":"Менелай сначала добивается жертвы, перехватывает письмо, но, увидев слёзы брата, отказывается от неё.","st":[{"i":463,"p":18,"l":"Действие первое · явление второе","t":"Перехват","d":"Отнимает у старого раба письмо Агамемнона.","c":"","k":false},{"i":621,"p":24,"l":"Действие первое · явление третье","t":"Ссора","d":"Обвиняет брата в непостоянстве и честолюбии.","c":"","k":false},{"i":833,"p":32,"l":"Действие первое · явление пятое","t":"Раскаяние","d":"Тронутый слезами брата, отказывается от жертвы.","c":"","k":true}],"gen":"Менелай"}]};
